import type { WisdomArticle } from "./types";
import { educationImages, eduImage } from "./education-images";

/** Articles sourced verbatim from temp-content/p4.txt (link-scrubbed, headings normalized) */
export const p4Articles: WisdomArticle[] = [
  {
    id: "planetary-strengths",
    section: "planets",
    title: { en: `Planetary Strengths or Powers`, hi: `ग्रहों की शक्तियाँ या शक्तियाँ`, ja: `惑星の強みまたは力`, ko: `행성의 강점 또는 힘`,},
    related: ["natural-benefics-malefics","planetary-karakas","planetary-aspects","twelve-houses"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Planetary Strengths or Powers`, hi: `ग्रहों की शक्तियाँ या शक्तियाँ`, ja: `惑星の強みまたは力`, ko: `행성의 강점 또는 힘`,} },
      { type: "paragraph", text: { en: `Summary: This article covers one of the most important aspects of chart interpretation—assessing the "strength," "power," or "status" of a planet based on its sign placement in a birth chart. It also explains the principles of sign ownership (rulership), the concepts of planetary "friends" and "enemies," and examines how retrograde motion, combustion, Vargottama status, divisional charts, and planetary war influence planetary strength.`, hi: `सारांश: यह लेख चार्ट व्याख्या के सबसे महत्वपूर्ण पहलुओं में से एक को शामिल करता है - जन्म कुंडली में उसके चिन्ह स्थान के आधार पर किसी ग्रह की "ताकत", "शक्ति" या "स्थिति" का आकलन करना। यह साइन ओनरशिप (शासन) के सिद्धांतों, ग्रहों के "मित्र" और "दुश्मनों" की अवधारणाओं को भी समझाता है और जांच करता है कि कैसे प्रतिगामी गति, दहन, वर्गोत्तम स्थिति, डिवीजनल चार्ट और ग्रह युद्ध ग्रहों की ताकत को प्रभावित करते हैं।`, ja: `概要: この記事では、出生図における星座の配置に基づいて惑星の「強さ」、「パワー」、または「ステータス」を評価するという、チャート解釈の最も重要な側面の 1 つについて説明します。また、記号の所有権 (支配者) の原則、惑星の「友人」と「敵」の概念も説明し、逆行、燃焼、ヴァルゴッタマのステータス、分割図、惑星戦争が惑星の強さにどのように影響するかを考察します。`, ko: `요약: 이 기사는 차트 해석의 가장 중요한 측면 중 하나, 즉 출생 차트의 별자리 위치를 기반으로 행성의 "강도", "힘" 또는 "상태"를 평가하는 방법을 다룹니다. 또한 기호 소유권(통치권)의 원리, 행성의 "친구"와 "적"의 개념을 설명하고 역행 운동, 연소, 바르고타마 상태, 분할 차트 및 행성 전쟁이 행성의 힘에 어떻게 영향을 미치는지 조사합니다.`,} },
      { type: "heading", level: 3, text: { en: `Sign ‘Ownership’ or ‘Rulership’ Principles`, hi: `'स्वामित्व' या 'शासन' सिद्धांतों पर हस्ताक्षर करें`, ja: `「所有権」または「支配者」の原則に署名する`, ko: `'소유권' 또는 '통치' 원칙에 서명하세요.`,} },
      { type: "paragraph", text: { en: `The Vedic seers assigned each sign of the zodiac to a particular planet.`, hi: `वैदिक ऋषियों ने राशि चक्र के प्रत्येक चिन्ह को एक विशेष ग्रह को निर्दिष्ट किया।`, ja: `ヴェーダの予言者たちは、黄道帯の各星座を特定の惑星に割り当てました。`, ko: `베다 선견자들은 황도대의 각 별자리를 특정 행성에 할당했습니다.`,} },
      { type: "heading", level: 3, text: { en: `Sign Ownership or Rulership by Planets in Jyotish`, hi: `ज्योतिष में ग्रहों द्वारा स्वामित्व या शासकत्व पर हस्ताक्षर करें`, ja: `ジョーティッシュの惑星による所有権または支配権に署名します`, ko: `Jyotish의 행성에 의한 소유권 또는 통치권 서명`,} },
      { type: "paragraph", text: { en: `For example, from the chart above we can see that the Sun is associated with the sign Leo. Therefore, the Sun is said to be the Owner or Ruler of Leo (sidereal).`, hi: `उदाहरण के लिए, ऊपर दिए गए चार्ट से हम देख सकते हैं कि सूर्य सिंह राशि से जुड़ा है। इसलिए, सूर्य को सिंह राशि (नाक्षत्र) का स्वामी या शासक कहा जाता है।`, ja: `たとえば、上のチャートから、太陽が獅子座に関連付けられていることがわかります。したがって、太陽は獅子座（恒星）の所有者または支配者であると言われています。`, ko: `예를 들어, 위의 차트에서 태양이 사자자리 기호와 연관되어 있음을 알 수 있습니다. 따라서 태양은 사자자리(항성)의 소유자 또는 통치자라고 합니다.`,} },
      { type: "paragraph", text: { en: `Notice that the Sun and Moon each rule only one sign, whereas the remaining visible planets—Mars, Mercury, Jupiter, Venus, and Saturn—each rule two signs. Thus, Jupiter rules Sagittarius and Pisces, Mercury rules Gemini and Virgo, and so on.`, hi: `ध्यान दें कि सूर्य और चंद्रमा प्रत्येक केवल एक ही राशि पर शासन करते हैं, जबकि शेष दृश्यमान ग्रह - मंगल, बुध, बृहस्पति, शुक्र और शनि - प्रत्येक दो राशियों पर शासन करते हैं। इस प्रकार, बृहस्पति धनु और मीन राशि पर शासन करता है, बुध मिथुन और कन्या राशि पर शासन करता है, इत्यादि।`, ja: `太陽と月はそれぞれ 1 つの星座のみを支配しますが、残りの目に見える惑星 (火星、水星、木星、金星、土星) はそれぞれ 2 つの星座を支配していることに注目してください。したがって、木星は射手座と魚座を支配し、水星は双子座と乙女座を支配します。`, ko: `태양과 달은 각각 하나의 별자리만을 지배하는 반면 나머지 눈에 보이는 행성인 화성, 수성, 목성, 금성, 토성은 각각 두 개의 별자리를 지배한다는 점에 유의하세요. 따라서 목성은 궁수자리와 물고기자리를 지배하고, 수성은 쌍둥이자리와 처녀자리를 지배하는 등입니다.`,} },
      { type: "paragraph", text: { en: `It is important to note that Rahu and Ketu do not own or rule any zodiac sign.`, hi: `यह ध्यान रखना महत्वपूर्ण है कि राहु और केतु किसी भी राशि के स्वामी या स्वामी नहीं हैं।`, ja: `ラーフとケートゥはどの星座も所有または支配していないことに注意することが重要です。`, ko: `라후와 케투는 황도대 별자리를 소유하거나 지배하지 않는다는 점에 유의하는 것이 중요합니다.`,} },
      { type: "heading", level: 3, text: { en: `Planetary ‘Strengths’ or ‘Powers’ – by Sign Placement`, hi: `ग्रहों की 'शक्तियाँ' या 'शक्तियाँ' - साइन प्लेसमेंट द्वारा`, ja: `惑星の「強み」または「力」 – 星座の配置による`, ko: `행성의 '강점' 또는 '능력' – 기호 배치별`,} },
      { type: "paragraph", text: { en: `In Jyotish, evaluating the strength or power of a planet is a fundamental part of chart interpretation.`, hi: `ज्योतिष में, किसी ग्रह की शक्ति या शक्ति का मूल्यांकन करना चार्ट व्याख्या का एक मूलभूत हिस्सा है।`, ja: `ジョーティッシュでは、惑星の強さやパワーを評価することがチャート解釈の基本的な部分です。`, ko: `Jyotish에서는 행성의 힘이나 힘을 평가하는 것이 차트 해석의 기본 부분입니다.`,} },
      { type: "paragraph", text: { en: `A planet regarded as strong tends to produce benefits and indicates positive returning karma. In general terms, a strong planet is usually considered a beneficial planet.`, hi: `एक ग्रह जिसे मजबूत माना जाता है वह लाभ उत्पन्न करता है और सकारात्मक रिटर्न वाले कर्म का संकेत देता है। सामान्य शब्दों में, एक मजबूत ग्रह को आमतौर पर लाभकारी ग्रह माना जाता है।`, ja: `強いとみなされる惑星は恩恵を生み出す傾向があり、ポジティブなカルマが戻ってくることを示しています。一般的に、強い惑星は通常、有益な惑星であると考えられます。`, ko: `강한 것으로 간주되는 행성은 이익을 창출하는 경향이 있으며 긍정적인 카르마 복귀를 나타냅니다. 일반적으로 강한 행성은 일반적으로 유익한 행성으로 간주됩니다.`,} },
      { type: "paragraph", text: { en: `There are two primary ways in which a strong planet produces positive results:`, hi: `ऐसे दो प्राथमिक तरीके हैं जिनसे एक मजबूत ग्रह सकारात्मक परिणाम देता है:`, ja: `強い惑星がポジティブな結果を生み出す主な方法は 2 つあります。`, ko: `강한 행성이 긍정적인 결과를 가져오는 두 가지 주요 방법이 있습니다.`,} },
      { type: "heading", level: 3, text: { en: `1. Benefits Through the Planet’s Natural Indications`, hi: `1. ग्रह के प्राकृतिक संकेतों से लाभ`, ja: `1. 地球の自然の兆候による恩恵`, ko: `1. 지구의 자연 징후를 통한 이점`,} },
      { type: "paragraph", text: { en: `A strong planet supports the life areas represented by its natural associations or Karakas.`, hi: `एक मजबूत ग्रह अपने प्राकृतिक संघों या कारक द्वारा दर्शाए गए जीवन क्षेत्रों का समर्थन करता है।`, ja: `強力な惑星は、自然の関連性またはカラカに代表される生命領域をサポートします。`, ko: `강한 행성은 자연적 연합, 즉 카라카스로 대표되는 생활 영역을 지원합니다.`,} },
      { type: "paragraph", text: { en: `For example, the Sun naturally signifies health, vitality, self-esteem, authority, power, and the relationship with one's father. Therefore, when the Sun is strong in a chart, we generally expect positive outcomes in these areas.`, hi: `उदाहरण के लिए, सूर्य स्वाभाविक रूप से स्वास्थ्य, जीवन शक्ति, आत्म-सम्मान, अधिकार, शक्ति और किसी के पिता के साथ संबंध का प्रतीक है। इसलिए, जब किसी चार्ट में सूर्य मजबूत होता है, तो हम आम तौर पर इन क्षेत्रों में सकारात्मक परिणामों की उम्मीद करते हैं।`, ja: `たとえば、太陽は当然、健康、活力、自尊心、権威、力、そして父親との関係を意味します。したがって、チャートで太陽が強い場合、一般的にこれらの分野でプラスの結果が期待されます。`, ko: `예를 들어, 태양은 자연스럽게 건강, 활력, 자존감, 권위, 힘, 아버지와의 관계를 의미합니다. 따라서 차트에서 태양이 강할 때 우리는 일반적으로 이러한 영역에서 긍정적인 결과를 기대합니다.`,} },
      { type: "paragraph", text: { en: `Similarly, the Moon naturally represents the mind, emotions, memory, and mental well-being. A strong Moon would therefore support emotional balance, memory, and mental stability.`, hi: `इसी प्रकार, चंद्रमा स्वाभाविक रूप से मन, भावनाओं, स्मृति और मानसिक कल्याण का प्रतिनिधित्व करता है। इसलिए एक मजबूत चंद्रमा भावनात्मक संतुलन, स्मृति और मानसिक स्थिरता का समर्थन करेगा।`, ja: `同様に、月は自然に心、感情、記憶、精神的な幸福を表します。したがって、強い月は感情的なバランス、記憶力、精神的な安定をサポートします。`, ko: `마찬가지로 달은 자연스럽게 마음, 감정, 기억, 정신적 안녕을 나타냅니다. 따라서 강한 달은 정서적 균형, 기억 및 정신적 안정을 지원합니다.`,} },
      { type: "heading", level: 3, text: { en: `2. Benefits Through the Houses the Planet Rules`, hi: `2. ग्रह जिन घरों पर शासन करता है उनके माध्यम से लाभ`, ja: `2. 惑星が支配する家を通じて得られる恩恵`, ko: `2. 지구가 통치하는 집을 통한 혜택`,} },
      { type: "paragraph", text: { en: `A strong planet also supports the houses associated with the signs that it owns or rules.`, hi: `एक मजबूत ग्रह उन राशियों से जुड़े घरों का भी समर्थन करता है जिन पर उसका स्वामित्व है या जिन पर वह शासन करता है।`, ja: `強い惑星は、それが所有または支配する星座に関連するハウスもサポートします。`, ko: `강한 행성은 또한 자신이 소유하거나 지배하는 별자리와 관련된 하우스를 지원합니다.`,} },
      { type: "paragraph", text: { en: `In Jyotish, each house encompasses an entire zodiac sign. Consequently, every house is connected to a particular sign and therefore to a ruling planet. When constructing a horoscope, the Ascendant sign becomes the first house.`, hi: `ज्योतिष में, प्रत्येक घर में एक संपूर्ण राशि शामिल होती है। नतीजतन, प्रत्येक घर एक विशेष राशि और इसलिए एक शासक ग्रह से जुड़ा होता है। कुंडली का निर्माण करते समय लग्न राशि ही प्रथम भाव बनती है।`, ja: `ジョーティッシュでは、各ハウスが星座全体を囲みます。その結果、すべてのハウスは特定のサインに接続され、したがって支配惑星に接続されます。ホロスコープを作成する場合、アセンダントサインが最初のハウスになります。`, ko: `Jyotish에서는 각 집이 전체 황도대 별자리를 포함합니다. 결과적으로 모든 하우스는 특정 별자리와 연결되어 지배 행성과 연결됩니다. 별자리를 구성할 때 승천 별자리가 첫 번째 하우스가 됩니다.`,} },
      { type: "paragraph", text: { en: `For example, if a person has Aries rising, Aries becomes the first house. To examine matters relating to children, we look to the 5th house. Counting clockwise from Aries, Leo becomes the 5th house. Since the Sun rules Leo, a strong Sun would positively influence the affairs of the 5th house, including children, education, intelligence, and creativity.`, hi: `उदाहरण के लिए, यदि किसी व्यक्ति की राशि मेष है, तो मेष राशि पहला घर बन जाती है। बच्चों से संबंधित मामलों की जांच के लिए हम पंचम भाव को देखते हैं। मेष राशि से दक्षिणावर्त गिनने पर सिंह राशि 5वां घर बन जाती है। चूंकि सूर्य सिंह राशि पर शासन करता है, इसलिए एक मजबूत सूर्य बच्चों, शिक्षा, बुद्धि और रचनात्मकता सहित 5वें घर के मामलों को सकारात्मक रूप से प्रभावित करेगा।`, ja: `たとえば、牡羊座が上昇している人は、牡羊座が最初の家になります。子供に関する問題を調べるには、5 ハウスに注目します。牡羊座から時計回りに数えると、獅子座は５室になります。太陽が獅子座を支配しているため、強い太陽は子供、教育、知性、創造性など、5室の事柄にプラスの影響を与えるでしょう。`, ko: `예를 들어, 어떤 사람이 양자리 상승을 가지고 있다면 양자리가 첫 번째 하우스가 됩니다. 아이들과 관련된 문제를 조사하려면 5하우스를 살펴보세요. 양자리를 기준으로 시계방향으로 계산하면 사자자리가 5하우스가 됩니다. 태양이 사자자리를 지배하기 때문에 강한 태양은 어린이, 교육, 지능, 창의성을 포함한 5하우스의 업무에 긍정적인 영향을 미칠 것입니다.`,} },
      { type: "paragraph", text: { en: `This support would come in addition to the Sun's natural indications such as health, confidence, and authority.`, hi: `यह समर्थन सूर्य के प्राकृतिक संकेतों जैसे स्वास्थ्य, आत्मविश्वास और अधिकार के अतिरिक्त मिलेगा।`, ja: `このサポートは、健康、自信、権威といった太陽の自然な兆候に加えて与えられるでしょう。`, ko: `이러한 지원은 건강, 자신감, 권위와 같은 태양의 자연적 징후에 추가로 제공됩니다.`,} },
      { type: "paragraph", text: { en: `To summarise, when a planet is strong, both its natural indications and the houses it rules receive support and benefit.`, hi: `संक्षेप में, जब कोई ग्रह मजबूत होता है, तो उसके प्राकृतिक संकेत और जिन घरों पर वह शासन करता है, दोनों को समर्थन और लाभ मिलता है।`, ja: `要約すると、惑星が強いとき、その自然の兆候とそれが支配するハウスの両方がサポートと恩恵を受けます。`, ko: `요약하자면, 행성이 강할 때 그 행성의 자연적 표시와 그것이 지배하는 하우스 모두 지원과 혜택을 받습니다.`,} },
      { type: "heading", level: 3, text: { en: `Assessing Planetary Strength from Sign Placement`, hi: `साइन प्लेसमेंट से ग्रहों की ताकत का आकलन`, ja: `ラーシの配置から惑星の強さを評価する`, ko: `라시 배치를 통해 행성의 강도 평가`,} },
      { type: "paragraph", text: { en: `Although planetary strength can be measured in numerous ways, one of the most important methods is by examining the zodiac sign in which the planet is placed.`, hi: `हालाँकि ग्रहों की ताकत को कई तरीकों से मापा जा सकता है, लेकिन सबसे महत्वपूर्ण तरीकों में से एक है उस राशि चक्र की जांच करना जिसमें ग्रह स्थित है।`, ja: `惑星の強さはさまざまな方法で測定できますが、最も重要な方法の 1 つは、惑星が配置されている星座を調べることです。`, ko: `행성의 강도는 다양한 방법으로 측정할 수 있지만 가장 중요한 방법 중 하나는 행성이 위치한 황도대 별자리를 조사하는 것입니다.`,} },
      { type: "paragraph", text: { en: `In some cases, the specific degree within a sign can also affect the level of strength.`, hi: `कुछ मामलों में, किसी चिन्ह के भीतर की विशिष्ट डिग्री भी ताकत के स्तर को प्रभावित कर सकती है।`, ja: `場合によっては、サイン内の特定の程度も強さのレベルに影響を与える可能性があります。`, ko: `어떤 경우에는 표지판 내의 특정 정도가 강도 수준에 영향을 미칠 수도 있습니다.`,} },
      { type: "paragraph", text: { en: `Vedic Astrology teaches that certain signs empower a planet and enable it to produce beneficial results, while other signs weaken it and may indicate challenges or more difficult returning karmas. Therefore, a planet's sign placement plays a major role in determining its strength.`, hi: `वैदिक ज्योतिष सिखाता है कि कुछ संकेत ग्रह को सशक्त बनाते हैं और उसे लाभकारी परिणाम देने में सक्षम बनाते हैं, जबकि अन्य संकेत इसे कमजोर करते हैं और चुनौतियों या अधिक कठिन रिटर्निंग कर्मों का संकेत दे सकते हैं। इसलिए, किसी ग्रह की राशि का स्थान उसकी ताकत निर्धारित करने में प्रमुख भूमिका निभाता है।`, ja: `ヴェーダ占星術は、特定の兆候が惑星に力を与え、有益な結果を生み出すことを可能にする一方で、他の兆候がそれを弱め、課題やより困難なカルマの帰還を示す可能性があると教えています。したがって、惑星の星座の配置は、その強さを決定する上で大きな役割を果たします。`, ko: `베다 점성술은 특정 별자리가 행성에 힘을 실어 유익한 결과를 낳을 수 있게 하는 반면, 다른 별자리는 행성을 약화시켜 어려움이나 카르마를 되돌리기 더 어려운 것을 나타낼 수 있다고 가르칩니다. 따라서 행성의 별자리 위치는 행성의 강도를 결정하는 데 중요한 역할을 합니다.`,} },
      { type: "paragraph", text: { en: `When first learning astrology, a useful approach is to identify whether each planet falls into one of four principal categories of strength.`, hi: `पहली बार ज्योतिष सीखते समय, एक उपयोगी दृष्टिकोण यह पहचानना है कि क्या प्रत्येक ग्रह शक्ति की चार प्रमुख श्रेणियों में से एक में आता है।`, ja: `初めて占星術を学ぶ場合、各惑星が強さの 4 つの主要なカテゴリーのいずれかに該当するかどうかを確認するのが便利なアプローチです。`, ko: `점성술을 처음 배울 때 유용한 접근 방식은 각 행성이 네 가지 주요 강도 범주 중 하나에 속하는지 확인하는 것입니다.`,} },
      { type: "paragraph", text: { en: `These are:`, hi: `ये हैं:`, ja: `これらは：`, ko: `이것들은 다음과 같습니다:`,} },
      { type: "paragraph", text: { en: `• Exalted`, hi: `• ऊंचा`, ja: `• 高揚した`, ko: `• 고귀한`,} },
      { type: "paragraph", text: { en: `• Moolatrikona`, hi: `• मूलत्रिकोण`, ja: `• ムーラトリコーナ`, ko: `• 물라트리코나`,} },
      { type: "paragraph", text: { en: `• Own Sign`, hi: `• अपना चिन्ह`, ja: `• 自分のサイン`, ko: `• 나만의 간판`,} },
      { type: "paragraph", text: { en: `• Debilitated (or Fallen)`, hi: `• दुर्बल (या पतित)`, ja: `• 衰弱した（または倒れた）`, ko: `• 쇠약해진(또는 타락한)`,} },
      { type: "paragraph", text: { en: `Exalted is the strongest condition, while Debilitated is the weakest. A planet placed in its Own Sign is generally considered strong and supportive.`, hi: `उच्च अवस्था सबसे मजबूत स्थिति होती है, जबकि नीच स्थिति सबसे कमजोर होती है। अपनी ही राशि में स्थित ग्रह को आम तौर पर मजबूत और सहायक माना जाता है।`, ja: `Exalted は最も強い状態であり、Debilitated は最も弱い状態です。自分の星座に位置する惑星は、一般的に強くて協力的であると考えられています。`, ko: `고귀함(Exalted)은 가장 강한 상태이고, 쇠약함(Debilitated)은 가장 약한 상태입니다. 자신의 별자리에 위치한 행성은 일반적으로 강력하고 지지적인 것으로 간주됩니다.`,} },
      { type: "paragraph", text: { en: `The state known as Moolatrikona has no direct English equivalent but is regarded as stronger than Own Sign and slightly below Exaltation.`, hi: `मूलत्रिकोना के नाम से जाने जाने वाले राज्य का कोई प्रत्यक्ष अंग्रेजी समकक्ष नहीं है, लेकिन इसे स्वयं के चिह्न से अधिक मजबूत और एक्साल्टेशन से थोड़ा नीचे माना जाता है।`, ja: `ムーラトリコーナとして知られる状態には、英語で直接的に相当するものはありませんが、オウンサインよりも強く、高揚よりわずかに下であると見なされています。`, ko: `물라트리코나(Moolatrikona)로 알려진 상태는 영어에 직접 상응하는 것이 없지만 Own Sign보다 강력하고 Exaltation보다 약간 낮은 것으로 간주됩니다.`,} },
      { type: "paragraph", text: { en: `The sign of debilitation is always located exactly 180 degrees opposite the sign of exaltation.`, hi: `नीच का चिन्ह हमेशा उच्च के चिन्ह के ठीक 180 डिग्री के विपरीत स्थित होता है।`, ja: `衰弱の兆候は常に高揚の兆候のちょうど 180 度反対に位置します。`, ko: `쇠약의 표시는 항상 승영의 표시와 정확히 180도 반대쪽에 위치합니다.`,} },
      { type: "paragraph", text: { en: `For example, Venus is naturally benefic. When Venus occupies Pisces, its sign of exaltation, it can produce significant benefits through both its natural indications and the houses associated with Taurus and Libra, the signs it rules.`, hi: `उदाहरण के लिए, शुक्र प्राकृतिक रूप से लाभकारी है। जब शुक्र अपनी उच्च राशि मीन पर कब्जा करता है, तो यह अपने प्राकृतिक संकेतों और वृषभ और तुला से जुड़े घरों, जिन राशियों पर यह शासन करता है, दोनों के माध्यम से महत्वपूर्ण लाभ पैदा कर सकता है।`, ja: `たとえば、金星はもともと恩恵を受けます。金星が高揚のサインである魚座を占めると、その自然の兆候と、金星が支配するサインであるおうし座と天秤座に関連するハウスの両方を通じて、大きな利益を生み出すことができます。`, ko: `예를 들어, 금성은 선천적으로 유익합니다. 금성이 승영의 표시인 물고기자리를 차지할 때 자연적 표시와 그것이 지배하는 표시인 황소자리 및 천칭자리와 관련된 하우스를 통해 상당한 이익을 얻을 수 있습니다.`,} },
      { type: "paragraph", text: { en: `However, when Venus occupies Virgo, its sign of debilitation, its ability to provide positive results is greatly reduced.`, hi: `हालाँकि, जब शुक्र अपनी नीच राशि कन्या में प्रवेश करता है, तो सकारात्मक परिणाम प्रदान करने की उसकी क्षमता बहुत कम हो जाती है।`, ja: `しかし、金星が衰弱の兆候である乙女座を占めると、前向きな結果をもたらす能力は大幅に低下します。`, ko: `그러나 금성이 쇠약함의 신호인 처녀자리를 차지하면 긍정적인 결과를 제공하는 능력이 크게 감소합니다.`,} },
      { type: "paragraph", text: { en: `A planet's capacity to produce beneficial outcomes therefore varies according to its strength, and its strength depends largely upon the sign in which it is placed.`, hi: `इसलिए किसी ग्रह की लाभकारी परिणाम देने की क्षमता उसकी ताकत के अनुसार भिन्न होती है, और उसकी ताकत काफी हद तक उस राशि पर निर्भर करती है जिसमें वह स्थित है।`, ja: `したがって、惑星が有益な結果を生み出す能力はその強さに応じて変化し、その強さは主にそれが配置されている星座に依存します。`, ko: `따라서 유익한 결과를 만들어내는 행성의 능력은 그 힘에 따라 달라지며, 그 힘은 주로 그것이 위치한 별자리에 따라 달라집니다.`,} },
      { type: "paragraph", text: { en: `The following sections provide the traditional strength classifications.`, hi: `निम्नलिखित अनुभाग पारंपरिक शक्ति वर्गीकरण प्रदान करते हैं।`, ja: `次のセクションでは、従来の強度分類について説明します。`, ko: `다음 섹션에서는 전통적인 강도 분류를 제공합니다.`,} },
      { type: "heading", level: 3, text: { en: `Planetary Strengths or Powers by Sign Placement`, hi: `साइन प्लेसमेंट द्वारा ग्रहों की ताकत या शक्तियां`, ja: `星座の配置による惑星の強さまたはパワー`, ko: `라시 배치에 따른 행성의 강점 또는 힘`,} },
      { type: "heading", level: 3, text: { en: `Sun (Surya)`, hi: `सूर्य (सूर्य)`, ja: `太陽（スーリヤ）`, ko: `태양(수리야)`,} },
      { type: "paragraph", text: { en: `• Exalted Sign: Aries (maximum strength at 10° Aries)`, hi: `• उच्च राशि: मेष (10° मेष पर अधिकतम शक्ति)`, ja: `• 高貴な星座: 牡羊座 (牡羊座 10° で最大の力)`, ko: `• 고귀한 별자리: 양자리(10° 양자리에서 최대 강도)`,} },
      { type: "paragraph", text: { en: `• Moolatrikona Sign: Leo 0°–20°`, hi: `• मूलत्रिकोण राशि: सिंह 0°-20°`, ja: `• ムーラトリコーナ星座: 獅子座 0°–20°`, ko: `• 물라트리코나 징후: 사자자리 0°–20°`,} },
      { type: "paragraph", text: { en: `• Own Sign: Leo 20°–30°`, hi: `• स्वयं की राशि: सिंह 20°-30°`, ja: `• 自分の星座: 獅子座 20°–30°`, ko: `• 자신의 사인: 사자자리 20°–30°`,} },
      { type: "paragraph", text: { en: `• Debilitated Sign: Libra (maximum weakness at 10° Libra)`, hi: `• नीच राशि: तुला (10° तुला पर अधिकतम कमजोरी)`, ja: `• 衰弱した星座：天秤座（天秤座10度で最大の弱さ）`, ko: `• 쇠약해진 징후: 천칭자리(10° 천칭자리에서 최대 약점)`,} },
      { type: "heading", level: 3, text: { en: `Moon (Chandra)`, hi: `चंद्रमा (चंद्र)`, ja: `ムーン（チャンドラ）`, ko: `문(찬드라)`,} },
      { type: "paragraph", text: { en: `• Exalted Sign: Taurus 0°–3°`, hi: `• उच्च राशि: वृषभ 0°-3°`, ja: `• 高貴な星座: おうし座 0°–3°`, ko: `• 고귀한 별자리: 황소자리 0°~3°`,} },
      { type: "paragraph", text: { en: `• Moolatrikona Sign: Taurus 3°–30°`, hi: `• मूलत्रिकोण राशि: वृषभ 3°-30°`, ja: `• ムーラトリコーナ星座: おうし座 3°–30°`, ko: `• 물라트리코나 징후: 황소자리 3°~30°`,} },
      { type: "paragraph", text: { en: `• Own Sign: Cancer`, hi: `• स्वराशि : कर्क`, ja: `• 自分の星座：蟹座`, ko: `• 자신의 징후: 암`,} },
      { type: "paragraph", text: { en: `• Debilitated Sign: Scorpio (maximum weakness at 3° Scorpio)`, hi: `• नीच राशि: वृश्चिक (3° वृश्चिक पर अधिकतम कमजोरी)`, ja: `• 衰弱した星座: 蠍座 (蠍座 3° で最大の衰弱)`, ko: `• 쇠약해진 징후: 전갈자리(3° 전갈자리에서 최대 약점)`,} },
      { type: "heading", level: 3, text: { en: `Mars (Mangala)`, hi: `मंगल (मंगल)`, ja: `火星 (マンガラ)`, ko: `화성(망갈라)`,} },
      { type: "paragraph", text: { en: `• Exalted Sign: Capricorn (maximum strength at 28° Capricorn)`, hi: `• उच्च राशि: मकर (अधिकतम शक्ति 28° मकर पर)`, ja: `• 高貴な星座: 山羊座 (山羊座 28° で最大の力)`, ko: `• 고귀한 별자리: 염소자리(28° 염소자리에서 최대 강도)`,} },
      { type: "paragraph", text: { en: `• Moolatrikona Sign: Aries 0°–12°`, hi: `• मूलत्रिकोण राशि: मेष 0°-12°`, ja: `• ムーラトリコーナ星座: 牡羊座 0°–12°`, ko: `• 물라트리코나 징후: 양자리 0°–12°`,} },
      { type: "paragraph", text: { en: `• Own Signs: Aries 12°–30° and Scorpio`, hi: `• स्वयं की राशियाँ: मेष 12°-30° और वृश्चिक`, ja: `• 自分の星座: 牡羊座 12°–30° と蠍座`, ko: `• 고유 별자리: 양자리 12°~30° 및 전갈자리`,} },
      { type: "paragraph", text: { en: `• Debilitated Sign: Cancer (maximum weakness at 28° Cancer)`, hi: `• दुर्बल राशि: कैंसर (28° कर्क राशि पर अधिकतम कमजोरी)`, ja: `• 衰弱の兆候: がん (がん 28° で最大の衰弱)`, ko: `• 쇠약 징후: 암(28° 암에서 최대 약화)`,} },
      { type: "heading", level: 3, text: { en: `Mercury (Buddha)`, hi: `बुध (बुद्ध)`, ja: `水星（仏陀）`, ko: `수성(부처)`,} },
      { type: "paragraph", text: { en: `• Exalted Sign: Virgo 0°–15° (maximum strength at 15° Virgo)`, hi: `• उच्च राशि: कन्या 0°-15° (अधिकतम शक्ति 15° कन्या पर)`, ja: `• 高貴な星座: 乙女座 0°–15° (乙女座 15° で最大の力)`, ko: `• 고귀한 별자리: 처녀자리 0°–15°(처녀자리 15°에서 최대 강도)`,} },
      { type: "paragraph", text: { en: `• Moolatrikona Sign: Virgo 16°–20°`, hi: `• मूलत्रिकोण राशि: कन्या 16°-20°`, ja: `• ムーラトリコーナ星座: おとめ座 16°–20°`, ko: `• 물라트리코나 징후: 처녀자리 16°–20°`,} },
      { type: "paragraph", text: { en: `• Own Signs: Virgo 20°–30° and Gemini`, hi: `• स्वयं की राशियाँ: कन्या राशि 20°-30° और मिथुन`, ja: `• 自分の星座: 乙女座 20°～30° と双子座`, ko: `• 자신의 별자리: 처녀자리 20°–30° 및 쌍둥이자리`,} },
      { type: "paragraph", text: { en: `• Debilitated Sign: Pisces (maximum weakness at 15° Pisces)`, hi: `• नीच राशि: मीन (15° मीन पर अधिकतम कमजोरी)`, ja: `• 衰弱した星座：魚座（魚座15°で最大の衰弱）`, ko: `• 쇠약해진 징후: 물고기자리(15° 물고기자리에서 최대 약점)`,} },
      { type: "heading", level: 3, text: { en: `Jupiter (Guru)`, hi: `बृहस्पति (गुरु)`, ja: `ジュピター (教祖)`, ko: `목성(구루)`,} },
      { type: "paragraph", text: { en: `• Exalted Sign: Cancer (maximum strength at 5° Cancer)`, hi: `• उच्च राशि: कर्क (5° कर्क पर अधिकतम शक्ति)`, ja: `• 高貴な星座：蟹座（蟹座5°で最大強度）`, ko: `• 고양 징후: 암(5° 암에서 최대 강도)`,} },
      { type: "paragraph", text: { en: `• Moolatrikona Sign: Sagittarius 0°–10°`, hi: `• मूलत्रिकोण राशि: धनु 0°-10°`, ja: `• ムーラトリコーナ星座: 射手座 0°–10°`, ko: `• 물라트리코나 별자리: 궁수자리 0°–10°`,} },
      { type: "paragraph", text: { en: `• Own Signs: Sagittarius 10°–30° and Pisces`, hi: `• स्वयं की राशियाँ: धनु 10°-30° और मीन`, ja: `• 自分の星座: 射手座 10°～30° と魚座`, ko: `• 고유 별자리: 궁수자리 10°~30° 및 물고기자리`,} },
      { type: "paragraph", text: { en: `• Debilitated Sign: Capricorn (maximum weakness at 5° Capricorn)`, hi: `• नीच राशि: मकर (5° मकर पर अधिकतम कमजोरी)`, ja: `• 衰弱した星座: 山羊座 (山羊座 5° で最大の弱さ)`, ko: `• 쇠약해진 징후: 염소자리(5° 염소자리에서 최대 약점)`,} },
      { type: "heading", level: 3, text: { en: `Venus (Shukra)`, hi: `शुक्र (शुक्र)`, ja: `ヴィーナス（シュクラ）`, ko: `비너스(슈크라)`,} },
      { type: "paragraph", text: { en: `• Exalted Sign: Pisces (maximum strength at 27° Pisces)`, hi: `• उच्च राशि: मीन (अधिकतम शक्ति 27° मीन पर)`, ja: `• 高貴な星座: 魚座 (魚座 27° で最大の力)`, ko: `• 고귀한 별자리: 물고기자리(27° 물고기자리에서 최대 강도)`,} },
      { type: "paragraph", text: { en: `• Moolatrikona Sign: Libra 0°–15° and Taurus`, hi: `• मूलत्रिकोण राशि: तुला 0°-15° और वृषभ`, ja: `• ムーラトリコーナ星座: 天秤座 0°–15° およびおうし座`, ko: `• 물라트리코나 징후: 천칭자리 0°–15° 및 황소자리`,} },
      { type: "paragraph", text: { en: `• Own Signs: Taurus 15°–30° and Libra`, hi: `• स्वयं की राशियाँ: वृषभ 15°-30° और तुला`, ja: `• 自分の星座: おうし座 15°–30° と天秤座`, ko: `• 고유 별자리: 황소자리 15°~30° 및 천칭자리`,} },
      { type: "paragraph", text: { en: `• Debilitated Sign: Virgo (maximum weakness at 27° Virgo)`, hi: `• नीच राशि: कन्या (27° कन्या राशि पर अधिकतम कमजोरी)`, ja: `• 衰弱した星座: 乙女座 (乙女座 27° で最大の衰弱)`, ko: `• 쇠약해진 징후: 처녀자리(처녀자리 27°에서 최대 약점)`,} },
      { type: "heading", level: 3, text: { en: `Saturn (Shani)`, hi: `शनि (शनि)`, ja: `サターン（シャニ）`, ko: `토성(샤니)`,} },
      { type: "paragraph", text: { en: `• Exalted Sign: Libra (maximum strength at 20° Libra)`, hi: `• उच्च राशि: तुला (अधिकतम शक्ति 20° तुला पर)`, ja: `• 高貴な星座: 天秤座 (天秤座 20°で最大の力)`, ko: `• 고귀한 표시: 천칭자리(20° 천칭자리에서 최대 강도)`,} },
      { type: "paragraph", text: { en: `• Moolatrikona Sign: Aquarius 0°–15°`, hi: `• मूलत्रिकोण राशि: कुंभ 0°-15°`, ja: `• ムーラトリコーナ星座: 水瓶座 0°–15°`, ko: `• 물라트리코나 징후: 물병자리 0°–15°`,} },
      { type: "paragraph", text: { en: `• Own Signs: Aquarius 15°–30° and Capricorn`, hi: `• स्वयं की राशियाँ: कुम्भ 15°-30° और मकर`, ja: `• 自分の星座: 水瓶座 15°～30° と山羊座`, ko: `• 고유 별자리: 물병자리 15°~30° 및 염소자리`,} },
      { type: "paragraph", text: { en: `• Debilitated Sign: Aries (maximum weakness at 20° Aries)`, hi: `• नीच राशि: मेष (20° मेष राशि पर अधिकतम कमजोरी)`, ja: `• 衰弱した星座: 牡羊座 (牡羊座 20° で最大の衰弱)`, ko: `• 쇠약해진 징후: 양자리(20° 양자리에서 최대 약점)`,} },
      { type: "heading", level: 3, text: { en: `Rahu`, hi: `राहु`, ja: `ラーフ`, ko: `라후`,} },
      { type: "paragraph", text: { en: `There is considerable variation among the ancient authorities regarding the signs where Rahu and Ketu are strongest or weakest. The following placements are based on the most reliable sources available.`, hi: `प्राचीन अधिकारियों के बीच उन संकेतों के संबंध में काफी भिन्नता है जहां राहु और केतु सबसे मजबूत या सबसे कमजोर हैं। निम्नलिखित प्लेसमेंट उपलब्ध सबसे विश्वसनीय स्रोतों पर आधारित हैं।`, ja: `ラーフとケートゥが最も強いまたは最も弱い兆候に関しては、古代の権威の間でかなりのばらつきがあります。以下の配置は、入手可能な最も信頼できる情報源に基づいています。`, ko: `라후와 케투가 가장 강하거나 가장 약한 표시에 관해 고대 권위자들 사이에는 상당한 차이가 있습니다. 다음 게재위치는 가장 신뢰할 수 있는 소스를 기반으로 합니다.`,} },
      { type: "paragraph", text: { en: `• Exalted Sign: Taurus`, hi: `• उच्च राशि: वृषभ`, ja: `• 高貴な星座：おうし座`, ko: `• 고귀한 별자리: 황소자리`,} },
      { type: "paragraph", text: { en: `• Debilitated Sign: Scorpio`, hi: `• नीच राशि: वृश्चिक`, ja: `• 衰弱した星座：蠍座`, ko: `• 쇠약해진 징후: 전갈자리`,} },
      { type: "heading", level: 3, text: { en: `Ketu`, hi: `केतु`, ja: `ケートゥ`, ko: `케투`,} },
      { type: "paragraph", text: { en: `• Exalted Sign: Scorpio`, hi: `• उच्च राशि: वृश्चिक`, ja: `• 高貴な星座：蠍座`, ko: `• 고귀한 표시: 전갈자리`,} },
      { type: "paragraph", text: { en: `• Debilitated Sign: Taurus`, hi: `• नीच राशि: वृषभ`, ja: `• 衰弱した星座：おうし座`, ko: `• 쇠약해진 징후: 황소자리`,} },
      { type: "heading", level: 3, text: { en: `Additional Measures of Strength – ‘Friends’ and ‘Enemies’`, hi: `ताकत के अतिरिक्त उपाय - 'मित्र' और 'दुश्मन'`, ja: `強さの追加の尺度 - 「友達」と「敵」`, ko: `추가적인 힘 측정 – '친구'와 '적'`,} },
      { type: "paragraph", text: { en: `Experienced astrologers use additional categories that lie between the states of Own Sign and Debilitation. These provide a more refined assessment of planetary condition.`, hi: `अनुभवी ज्योतिषी अतिरिक्त श्रेणियों का उपयोग करते हैं जो स्वराशि और दुर्बलता की अवस्थाओं के बीच स्थित होती हैं। ये ग्रहों की स्थिति का अधिक परिष्कृत मूल्यांकन प्रदान करते हैं।`, ja: `経験豊富な占星術師は、自分の星座と衰弱の状態の間にある追加のカテゴリーを使用します。これらは、惑星の状態のより洗練された評価を提供します。`, ko: `숙련된 점성가들은 자신의 별자리와 쇠약 상태 사이에 있는 추가 범주를 사용합니다. 이는 행성 상태에 대한 보다 정교한 평가를 제공합니다.`,} },
      { type: "paragraph", text: { en: `Three important intermediate categories are:`, hi: `तीन महत्वपूर्ण मध्यवर्ती श्रेणियां हैं:`, ja: `3 つの重要な中間カテゴリは次のとおりです。`, ko: `세 가지 중요한 중간 범주는 다음과 같습니다.`,} },
      { type: "paragraph", text: { en: `• Friend`, hi: `• दोस्त`, ja: `• 友達`, ko: `• 친구`,} },
      { type: "paragraph", text: { en: `• Neutral`, hi: `• तटस्थ`, ja: `• ニュートラル`, ko: `• 중립적`,} },
      { type: "paragraph", text: { en: `• Enemy`, hi: `• दुश्मन`, ja: `• 敵`, ko: `• 적`,} },
      { type: "paragraph", text: { en: `A planet placed in a sign ruled by a friendly planet tends to function well, whereas a planet occupying the sign of an enemy is weakened.`, hi: `मित्र ग्रह द्वारा शासित राशि में स्थित ग्रह अच्छी तरह से कार्य करता है, जबकि शत्रु राशि में स्थित ग्रह कमजोर हो जाता है।`, ja: `友好的な惑星が支配する星座に位置する惑星はうまく機能する傾向にありますが、敵の星座にある惑星は弱体化します。`, ko: `아군 행성이 지배하는 별자리에 위치한 행성은 잘 기능하는 경향이 있는 반면, 적의 별자리를 차지하는 행성은 약화됩니다.`,} },
      { type: "paragraph", text: { en: `Of course, planets do not literally have friends or enemies. These terms simply indicate that certain planetary environments are more supportive than others. For example, Venus is considered less comfortable and therefore less productive when placed in a sign ruled by an enemy such as the Sun.`, hi: `निःसंदेह, ग्रहों के वस्तुतः मित्र या शत्रु नहीं होते। ये शब्द केवल यह संकेत देते हैं कि कुछ ग्रहीय वातावरण दूसरों की तुलना में अधिक सहायक हैं। उदाहरण के लिए, सूर्य जैसे शत्रु द्वारा शासित राशि में स्थित होने पर शुक्र को कम आरामदायक और इसलिए कम उत्पादक माना जाता है।`, ja: `もちろん、惑星には文字通り友人や敵がいるわけではありません。これらの用語は、特定の惑星環境が他の惑星環境よりも支援的であることを単に示しています。たとえば、金星が太陽などの敵に支配される星座に配置されると、快適性が低下し、生産性が低下すると考えられます。`, ko: `물론, 행성에는 말 그대로 친구나 적이 없습니다. 이 용어는 단순히 특정 행성 환경이 다른 환경보다 더 도움이 된다는 것을 나타냅니다. 예를 들어, 금성은 태양과 같은 적의 지배를 받는 별자리에 배치될 때 덜 편안하고 따라서 생산성이 떨어지는 것으로 간주됩니다.`,} },
      { type: "paragraph", text: { en: `In addition to these permanent friendship categories, Jyotish also recognises temporary friendships based upon the relative positions of planets within a chart. These create two additional classifications:`, hi: `इन स्थायी मित्रता श्रेणियों के अलावा, ज्योतिष चार्ट के भीतर ग्रहों की सापेक्ष स्थिति के आधार पर अस्थायी मित्रता को भी मान्यता देता है। ये दो अतिरिक्त वर्गीकरण बनाते हैं:`, ja: `これらの永続的な友情カテゴリーに加えて、ジョーティッシュは、チャート内の惑星の相対的な位置に基づいて一時的な友情も認識します。これらにより、次の 2 つの追加の分類が作成されます。`, ko: `이러한 영구적인 우정 범주 외에도 Jyotish는 차트 내 행성의 상대적 위치를 기반으로 일시적인 우정을 인식합니다. 이를 통해 두 가지 추가 분류가 생성됩니다.`,} },
      { type: "paragraph", text: { en: `• Great Friend`, hi: `• घनिष्ठ मित्र`, ja: `• 素晴らしい友達`, ko: `• 좋은 친구`,} },
      { type: "paragraph", text: { en: `• Great Enemy`, hi: `• महान शत्रु`, ja: `• 大きな敵`, ko: `• 큰 적`,} },
      { type: "paragraph", text: { en: `Although charts and rules exist to determine these relationships, they can be challenging for beginners to memorise. Fortunately, most good Vedic Astrology software calculates these conditions automatically.`, hi: `हालाँकि इन रिश्तों को निर्धारित करने के लिए चार्ट और नियम मौजूद हैं, लेकिन शुरुआती लोगों के लिए इन्हें याद रखना चुनौतीपूर्ण हो सकता है। सौभाग्य से, अधिकांश अच्छे वैदिक ज्योतिष सॉफ़्टवेयर इन स्थितियों की स्वचालित रूप से गणना करते हैं।`, ja: `これらの関係を判断するための図表やルールは存在しますが、初心者にとってそれらを覚えるのは難しい場合があります。幸いなことに、優れたヴェーダ占星術ソフトウェアのほとんどは、これらの条件を自動的に計算します。`, ko: `이러한 관계를 결정하기 위한 차트와 규칙이 존재하지만 초보자가 기억하기 어려울 수 있습니다. 다행스럽게도 대부분의 우수한 베다 점성술 소프트웨어는 이러한 조건을 자동으로 계산합니다.`,} },
      { type: "paragraph", text: { en: `Together with the categories of Exalted, Moolatrikona, Own Sign, and Debilitated, these friendship classifications form the primary planetary states or Avasthas used in chart interpretation.`, hi: `उच्च, मूलत्रिकोण, स्वराशि और नीच की श्रेणियों के साथ, ये मैत्री वर्गीकरण चार्ट व्याख्या में उपयोग की जाने वाली प्राथमिक ग्रह अवस्थाओं या अवस्था का निर्माण करते हैं।`, ja: `これらの友情の分類は、高揚、ムーラトリコーナ、オウンサイン、衰弱のカテゴリーとともに、チャートの解釈に使用される主要な惑星国家またはアヴァスタを形成します。`, ko: `Exalted, Moolatrikona, Own Sign 및 Debilitated 범주와 함께 이러한 우정 분류는 차트 해석에 사용되는 주요 행성 상태 또는 Avasthas를 형성합니다.`,} },
      { type: "paragraph", text: { en: `For a complete analysis, all nine categories should be considered. However, beginners can gain surprisingly accurate insights simply by focusing on the four major states: Exalted, Moolatrikona, Own Sign, and Debilitated.`, hi: `संपूर्ण विश्लेषण के लिए सभी नौ श्रेणियों पर विचार किया जाना चाहिए। हालाँकि, शुरुआती लोग केवल चार प्रमुख स्थितियों पर ध्यान केंद्रित करके आश्चर्यजनक रूप से सटीक अंतर्दृष्टि प्राप्त कर सकते हैं: उच्च, मूलत्रिकोण, स्वयं की राशि और नीच राशि।`, ja: `完全な分析を行うには、9 つ​​のカテゴリすべてを考慮する必要があります。ただし、初心者は、高揚、ムーラトリコーナ、オウンサイン、衰弱の 4 つの主要な状態に焦点を当てるだけで、驚くほど正確な洞察を得ることができます。`, ko: `완전한 분석을 위해서는 9가지 범주를 모두 고려해야 합니다. 그러나 초보자는 Exalted, Moolatrikona, Own Sign 및 Debilitated의 네 가지 주요 상태에 집중함으로써 놀랍도록 정확한 통찰력을 얻을 수 있습니다.`,} },
      { type: "paragraph", text: { en: `The sage Parashara quantified the relative benefits of these states as follows:`, hi: `ऋषि पराशर ने इन राज्यों के सापेक्ष लाभों को इस प्रकार निर्धारित किया:`, ja: `賢者パラシャラは、これらの州の相対的な利点を次のように定量化しました。`, ko: `현자 Parashara는 이러한 상태의 상대적 이점을 다음과 같이 수량화했습니다.`,} },
      { type: "paragraph", text: { en: `• Exalted: 100%`, hi: `• श्रेष्ठ: 100%`, ja: `• 高揚: 100%`, ko: `• 확고한 동맹: 100%`,} },
      { type: "paragraph", text: { en: `• Moolatrikona: 75%`, hi: `• मूलत्रिकोण: 75%`, ja: `• ムーラトリコーナ: 75%`, ko: `• 물라트리코나: 75%`,} },
      { type: "paragraph", text: { en: `• Own Sign: 50%`, hi: `• अपना चिन्ह: 50%`, ja: `• 自分のサイン: 50%`, ko: `• 자체 서명: 50%`,} },
      { type: "paragraph", text: { en: `• Friendly Sign: 25%`, hi: `• मित्र राशि: 25%`, ja: `• フレンドリーサイン: 25%`, ko: `• 우호적 표시: 25%`,} },
      { type: "paragraph", text: { en: `• Neutral Sign: 12%`, hi: `• तटस्थ चिह्न: 12%`, ja: `• ニュートラルサイン: 12%`, ko: `• 중립부호: 12%`,} },
      { type: "paragraph", text: { en: `• Fallen/Enemy Sign: 0%`, hi: `• पतित/शत्रु चिन्ह: 0%`, ja: `• フォールン/敵のサイン: 0%`, ko: `• 쓰러짐/적 징후: 0%`,} },
      { type: "paragraph", text: { en: `These figures should not be interpreted too literally, but they provide a useful illustration of how planetary condition influences its ability to produce positive results.`, hi: `इन आंकड़ों की बहुत शाब्दिक व्याख्या नहीं की जानी चाहिए, लेकिन वे इस बात का एक उपयोगी उदाहरण प्रदान करते हैं कि ग्रहों की स्थिति सकारात्मक परिणाम देने की क्षमता को कैसे प्रभावित करती है।`, ja: `これらの数字はあまり文字通りに解釈すべきではありませんが、惑星の状態がポジティブな結果を生み出す能力にどのような影響を与えるかを示す有益な図を提供します。`, ko: `이 수치를 너무 문자 그대로 해석해서는 안 되지만, 행성의 상태가 긍정적인 결과를 생성하는 능력에 어떻게 영향을 미치는지에 대한 유용한 예시를 제공합니다.`,} },
      { type: "paragraph", text: { en: `The chart below summarises these relationships.`, hi: `नीचे दिया गया चार्ट इन संबंधों का सारांश प्रस्तुत करता है।`, ja: `以下の図は、これらの関係をまとめたものです。`, ko: `아래 차트에는 이러한 관계가 요약되어 있습니다.`,} },
      { type: "paragraph", text: { en: `Please remember that the categories of Great Friend and Great Enemy depend upon temporary planetary relationships within a particular chart and are therefore not fixed.`, hi: `कृपया याद रखें कि महान मित्र और महान शत्रु की श्रेणियां एक विशेष चार्ट के भीतर अस्थायी ग्रह संबंधों पर निर्भर करती हैं और इसलिए तय नहीं होती हैं।`, ja: `偉大な友人と偉大な敵のカテゴリーは、特定のチャート内の一時的な惑星の関係に依存するため、固定されていないことに注意してください。`, ko: `큰 친구와 큰 적의 범주는 특정 차트 내의 일시적인 행성 관계에 따라 달라지므로 고정되지 않는다는 점을 기억하십시오.`,} },
      { type: "heading", level: 3, text: { en: `Planetary Strengths by Sign Placement – Nine Categories or States in Jyotish`, hi: `साइन प्लेसमेंट द्वारा ग्रहों की ताकत - ज्योतिष में नौ श्रेणियां या राज्य`, ja: `星座の配置による惑星の強さ – ジョーティッシュの 9 つのカテゴリーまたは州`, ko: `라시 배치에 따른 행성의 강점 – Jyotish의 9개 범주 또는 주`,} },
      { type: "paragraph", text: { en: `A table showing the relationship between sign placement (Exalted, Own Sign, etc.) and resulting planetary strength in Jyotish Astrology.`, hi: `ज्योतिष में साइन प्लेसमेंट (उच्च, स्वराशि, आदि) और परिणामी ग्रह शक्ति के बीच संबंध दिखाने वाली एक तालिका।`, ja: `ジョーティッシュにおけるサインの配置 (Exalted、Own Sign など) とその結果として生じる惑星の強さの関係を示す表。`, ko: `Jyotish Astrology에서 별자리 배치(Exalted, Own Sign 등)와 그에 따른 행성 강도 사이의 관계를 보여주는 표입니다.`,} },
      { type: "heading", level: 3, text: { en: `Other Factors Which Influence Planetary Strength`, hi: `अन्य कारक जो ग्रहों की शक्ति को प्रभावित करते हैं`, ja: `惑星の強度に影響を与えるその他の要因`, ko: `행성 강도에 영향을 미치는 기타 요소`,} },
      { type: "paragraph", text: { en: `Several additional factors can modify planetary strength.`, hi: `कई अतिरिक्त कारक ग्रहों की ताकत को संशोधित कर सकते हैं।`, ja: `いくつかの追加要因が惑星の強度を変更する可能性があります。`, ko: `몇 가지 추가 요소가 행성의 강도를 수정할 수 있습니다.`,} },
      { type: "paragraph", text: { en: `These include:`, hi: `इसमे शामिल है:`, ja: `これらには次のものが含まれます。`, ko: `여기에는 다음이 포함됩니다.`,} },
      { type: "paragraph", text: { en: `• Retrograde motion`, hi: `• प्रतिगामी गति`, ja: `• 逆行運動`, ko: `• 역행 운동`,} },
      { type: "paragraph", text: { en: `• Combustion`, hi: `• दहन`, ja: `• 燃焼`, ko: `• 연소`,} },
      { type: "paragraph", text: { en: `• Planetary War`, hi: `• ग्रह युद्ध`, ja: `• 惑星戦争`, ko: `• 행성 전쟁`,} },
      { type: "paragraph", text: { en: `• Position in divisional charts`, hi: `• संभागीय चार्ट में स्थिति`, ja: `• 部門別チャートでの位置`, ko: `• 분할 차트에서의 위치`,} },
      { type: "paragraph", text: { en: `If you are completely new to Jyotish, you may wish to skip this section initially and return to it later.`, hi: `यदि आप ज्योतिष में बिल्कुल नए हैं, तो हो सकता है कि आप शुरुआत में इस अनुभाग को छोड़ना चाहें और बाद में इस पर वापस लौटना चाहें।`, ja: `Jotish をまったく初めて使用する場合は、最初はこのセクションをスキップして、後で戻ってくることをお勧めします。`, ko: `Jyotish를 완전히 처음 사용하는 경우 처음에는 이 섹션을 건너뛰고 나중에 다시 돌아올 수 있습니다.`,} },
      { type: "heading", level: 3, text: { en: `Effects of Aspects on Planetary Strength`, hi: `ग्रहों की शक्ति पर पहलुओं का प्रभाव`, ja: `惑星の強さに対するアスペクトの影響`, ko: `행성의 힘에 대한 측면의 영향`,} },
      { type: "paragraph", text: { en: `Planets receiving aspects from benefic planets such as Jupiter, Venus, Mercury, and the Moon gain strength. Consequently, both their natural indications and the houses they rule are enhanced.`, hi: `बृहस्पति, शुक्र, बुध और चंद्रमा जैसे शुभ ग्रहों से दृष्टि प्राप्त करने वाले ग्रह बल प्राप्त करते हैं। नतीजतन, उनके प्राकृतिक संकेत और जिन घरों पर वे शासन करते हैं, दोनों में वृद्धि होती है।`, ja: `木星、金星、水星、月などの吉星からアスペクトを受けている惑星は力を増します。その結果、彼らの自然な兆候と彼らが統治する家の両方が強化されます。`, ko: `목성, 금성, 수성, 달과 같은 유익한 행성으로부터 측면을 받는 행성은 힘을 얻습니다. 결과적으로, 그들의 자연적 징후와 그들이 지배하는 집이 모두 향상됩니다.`,} },
      { type: "paragraph", text: { en: `Aspects in Jyotish are more sophisticated than those used in Western Astrology.`, hi: `ज्योतिष के पहलू पश्चिमी ज्योतिष में प्रयुक्त पहलुओं की तुलना में अधिक परिष्कृत हैं।`, ja: `ジョーティッシュのアスペクトは西洋占星術で使用されるアスペクトよりも洗練されています。`, ko: `Jyotish의 측면은 서양 점성술에서 사용되는 측면보다 더 정교합니다.`,} },
      { type: "paragraph", text: { en: `Planets receiving aspects from malefics such as Mars and Saturn become weakened. As a result, their indications and the houses they govern may experience challenges.`, hi: `मंगल और शनि जैसे पाप ग्रहों से दृष्टि प्राप्त करने वाले ग्रह कमजोर हो जाते हैं। परिणामस्वरूप, उनके संकेत और जिन घरों पर वे शासन करते हैं उन्हें चुनौतियों का सामना करना पड़ सकता है।`, ja: `火星や土星など凶星からのアスペクトを受けている惑星は弱まってしまいます。その結果、彼らの兆候と彼らが統治する家は困難に直面する可能性があります。`, ko: `화성과 토성과 같은 재앙으로부터 측면을 받는 행성은 약화됩니다. 결과적으로, 그들의 징후와 그들이 통치하는 가문은 어려움을 겪을 수 있습니다.`,} },
      { type: "paragraph", text: { en: `Note: Rahu and Ketu do not cast aspects.`, hi: `नोट: राहु और केतु की दृष्टि नहीं पड़ती।`, ja: `注: ラーフとケートゥはアスペクトをキャストしません。`, ko: `참고: 라후와 케투는 측면을 시전하지 않습니다.`,} },
      { type: "heading", level: 3, text: { en: `Effect of Combust Planets in Vedic Astrology`, hi: `वैदिक ज्योतिष में अस्त ग्रहों का प्रभाव`, ja: `ヴェーダ占星術における燃焼惑星の影響`, ko: `베다 점성술에서 연소 행성의 효과`,} },
      { type: "paragraph", text: { en: `When a planet comes too close to the Sun, it can become combust, meaning its ability to produce positive results is reduced.`, hi: `जब कोई ग्रह सूर्य के बहुत करीब आ जाता है, तो वह अस्त हो सकता है, जिसका अर्थ है कि सकारात्मक परिणाम देने की उसकी क्षमता कम हो जाती है।`, ja: `惑星が太陽に近づきすぎると、惑星が燃焼する可能性があり、肯定的な結果を生み出す能力が低下することを意味します。`, ko: `행성이 태양에 너무 가까워지면 연소될 수 있으며, 이는 긍정적인 결과를 생성하는 능력이 감소한다는 것을 의미합니다.`,} },
      { type: "paragraph", text: { en: `This negatively affects both its natural indications and the houses it rules.`, hi: `यह इसके प्राकृतिक संकेतों और जिन घरों पर यह शासन करता है, दोनों पर नकारात्मक प्रभाव डालता है।`, ja: `これは、その自然の兆候とそれが統治する家の両方に悪影響を及ぼします。`, ko: `이는 자연적 징후와 그것이 지배하는 주택 모두에 부정적인 영향을 미칩니다.`,} },
      { type: "paragraph", text: { en: `Mercury frequently becomes combust because it always remains relatively close to the Sun. Venus also commonly experiences combustion. When Venus appears as the Morning Star before sunrise, it is necessarily positioned fairly close to the Sun.`, hi: `बुध अक्सर अस्त हो जाता है क्योंकि यह हमेशा सूर्य के अपेक्षाकृत करीब रहता है। शुक्र भी आमतौर पर दहन का अनुभव करता है। जब शुक्र सूर्योदय से पहले सुबह के तारे के रूप में दिखाई देता है, तो यह आवश्यक रूप से सूर्य के काफी करीब स्थित होता है।`, ja: `水星は常に太陽に比較的近い位置にあるため、頻繁に燃焼します。金星もよく燃焼を経験します。金星が日の出前に明けの明星として現れるとき、それは必然的に太陽のかなり近くに位置します。`, ko: `수성은 항상 태양에 상대적으로 가까이 있기 때문에 자주 연소됩니다. 금성은 또한 일반적으로 연소를 경험합니다. 금성이 해가 뜨기 전에 새벽별처럼 나타날 때, 그것은 필연적으로 태양에 상당히 가까이 위치하게 됩니다.`,} },
      { type: "paragraph", text: { en: `Generally, combustion occurs when a planet is within approximately 10 to 15 degrees of the Sun. However, the precise range varies according to the planet involved and whether it is moving direct or retrograde.`, hi: `आम तौर पर, दहन तब होता है जब कोई ग्रह सूर्य के लगभग 10 से 15 डिग्री के भीतर होता है। हालाँकि, सटीक सीमा संबंधित ग्रह के अनुसार भिन्न होती है और चाहे वह सीधी गति से चल रहा हो या प्रतिगामी गति से।`, ja: `一般に、燃焼は惑星が太陽から約 10 ～ 15 度以内にあるときに発生します。ただし、正確な範囲は、関係する惑星と、それが順行しているか逆行しているかによって異なります。`, ko: `일반적으로 연소는 행성이 태양으로부터 약 10~15도 내에 있을 때 발생합니다. 그러나 정확한 범위는 관련된 행성과 그것이 직접 이동하는지 역행하는지 여부에 따라 다릅니다.`,} },
      { type: "paragraph", text: { en: `Rahu and Ketu never become combust.`, hi: `राहु और केतु कभी अस्त नहीं होते।`, ja: `ラーフとケートゥは決して燃焼しません。`, ko: `Rahu와 Ketu는 결코 연소되지 않습니다.`,} },
      { type: "paragraph", text: { en: `Therefore, whenever a planet lies very close to the Sun, combustion should be investigated further.`, hi: `इसलिए, जब भी कोई ग्रह सूर्य के बहुत करीब होता है, तो दहन की आगे जांच की जानी चाहिए।`, ja: `したがって、惑星が太陽のすぐ近くにある場合には、燃焼をさらに詳しく調査する必要があります。`, ko: `따라서 행성이 태양에 매우 가까이 있을 때마다 연소에 대한 추가 조사가 필요합니다.`,} },
      { type: "heading", level: 3, text: { en: `Effect of Retrograde Planets in Jyotish`, hi: `ज्योतिष में वक्री ग्रहों का प्रभाव`, ja: `ジョーティッシュにおける逆行惑星の影響`, ko: `Jyotish에서 역행 행성의 효과`,} },
      { type: "paragraph", text: { en: `Another important factor influencing planetary status is retrograde motion.`, hi: `ग्रहों की स्थिति को प्रभावित करने वाला एक अन्य महत्वपूर्ण कारक प्रतिगामी गति है।`, ja: `惑星の状態に影響を与えるもう 1 つの重要な要素は、逆行運動です。`, ko: `행성 상태에 영향을 미치는 또 다른 중요한 요소는 역행 운동입니다.`,} },
      { type: "paragraph", text: { en: `No physical planet actually reverses its orbit around the Sun. However, due to the relative motions of Earth and the planets, they may appear to move backwards against the background of the fixed stars and constellations. This apparent reversal is known as retrograde motion.`, hi: `वास्तव में कोई भी भौतिक ग्रह सूर्य के चारों ओर अपनी कक्षा नहीं बदलता है। हालाँकि, पृथ्वी और ग्रहों की सापेक्ष गति के कारण, वे स्थिर तारों और नक्षत्रों की पृष्ठभूमि के विपरीत पीछे की ओर बढ़ते हुए प्रतीत हो सकते हैं। इस स्पष्ट उलटफेर को प्रतिगामी गति के रूप में जाना जाता है।`, ja: `実際に太陽の周りの軌道を反転する物理的な惑星はありません。ただし、地球と惑星の相対運動により、恒星や星座を背景にそれらが逆に動いているように見える場合があります。この見かけの逆転は、逆行運動として知られています。`, ko: `어떤 물리적 행성도 실제로 태양 주위의 궤도를 바꾸지 않습니다. 그러나 지구와 행성의 상대적인 움직임으로 인해 항성과 별자리를 배경으로 뒤로 움직이는 것처럼 보일 수 있습니다. 이러한 겉보기 반전을 역행 운동이라고 합니다.`,} },
      { type: "paragraph", text: { en: `Although astrologers differ somewhat in their interpretations, the general consensus is that retrograde planets gain strength. Since strength is usually regarded as beneficial in Jyotish, retrogression is often viewed positively.`, hi: `हालाँकि ज्योतिषी अपनी व्याख्याओं में कुछ भिन्न हैं, लेकिन आम सहमति यह है कि प्रतिगामी ग्रह ताकत हासिल करते हैं। चूँकि ज्योतिष में शक्ति को आमतौर पर लाभकारी माना जाता है, प्रतिगमन को अक्सर सकारात्मक रूप से देखा जाता है।`, ja: `占星術師によって解釈が多少異なりますが、逆行する惑星が力を増すというのが一般的な見解です。ジョーティッシュでは通常、強さは有益であると考えられているため、退行はしばしば肯定的に見られます。`, ko: `점성가들의 해석은 다소 다르지만, 역행 행성이 힘을 얻는다는 것이 일반적인 합의입니다. 힘은 일반적으로 Jyotish에서 유익한 것으로 간주되기 때문에 퇴행은 종종 긍정적으로 간주됩니다.`,} },
      { type: "paragraph", text: { en: `This view is supported by the observation that retrograde planets generally need to move closer to the Sun before combustion occurs.`, hi: `यह दृष्टिकोण इस अवलोकन से समर्थित है कि प्रतिगामी ग्रहों को आम तौर पर दहन होने से पहले सूर्य के करीब जाने की आवश्यकता होती है।`, ja: `この見解は、逆行惑星は一般に燃焼が起こる前に太陽に近づく必要があるという観察によって裏付けられています。`, ko: `이 견해는 역행 행성이 일반적으로 연소가 발생하기 전에 태양에 더 가까이 이동해야 한다는 관찰에 의해 뒷받침됩니다.`,} },
      { type: "heading", level: 3, text: { en: `Planets with Vargottama Status`, hi: `वर्गोत्तम स्थिति वाले ग्रह`, ja: `ヴァルゴッタマステータスを持つ惑星`, ko: `바르고타마 상태의 행성`,} },
      { type: "paragraph", text: { en: `Vargottama is another factor that modifies planetary condition.`, hi: `वर्गोत्तम एक अन्य कारक है जो ग्रह स्थिति को संशोधित करता है।`, ja: `ヴァルゴッタマは惑星の状態を変えるもう一つの要因です。`, ko: `Vargottama는 행성 상태를 수정하는 또 다른 요소입니다.`,} },
      { type: "paragraph", text: { en: `Beginners are often advised not to focus heavily on the divisional charts or Vargas. Nevertheless, the Navamsha chart (the ninth divisional chart) is especially important, not only for marriage and partnerships but also for assessing planetary strength.`, hi: `शुरुआती लोगों को अक्सर सलाह दी जाती है कि वे डिविजनल चार्ट या वर्गास पर अधिक ध्यान न दें। फिर भी, नवमांश चार्ट (नौवां मंडल चार्ट) विशेष रूप से महत्वपूर्ण है, न केवल विवाह और साझेदारी के लिए बल्कि ग्रहों की ताकत का आकलन करने के लिए भी।`, ja: `初心者は、部門チャートやバルガスにあまり集中しないようによくアドバイスされます。それにもかかわらず、ナヴァムシャ チャート (9 番目の区分チャート) は、結婚やパートナーシップだけでなく、惑星の強さを評価するためにも特に重要です。`, ko: `초보자는 디비전 차트나 바르가스에 너무 집중하지 말라고 조언하는 경우가 많습니다. 그럼에도 불구하고 Navamsha 차트(9번째 구분 차트)는 결혼과 파트너십뿐만 아니라 행성의 힘을 평가하는 데에도 특히 중요합니다.`,} },
      { type: "paragraph", text: { en: `A planet occupying the same sign in both the main birth chart and the Navamsha chart is said to be Vargottama.`, hi: `मुख्य जन्म कुंडली और नवमांश कुंडली दोनों में एक ही राशि में स्थित ग्रह को वर्गोत्तम कहा जाता है।`, ja: `メイン出生図とナヴァムシャ図の両方で同じ星座を占める惑星はヴァルゴッタマであると言われています。`, ko: `주요 출생 차트와 Navamsha 차트에서 동일한 별자리를 차지하는 행성은 Vargottama라고 합니다.`,} },
      { type: "paragraph", text: { en: `This condition strengthens the planet considerably and is generally regarded as being at least equivalent to Own Sign status.`, hi: `यह स्थिति ग्रह को काफी मजबूत करती है और आम तौर पर इसे कम से कम अपनी राशि की स्थिति के बराबर माना जाता है।`, ja: `この状態は惑星を大幅に強化し、一般に少なくとも自分の星座のステータスと同等であると見なされます。`, ko: `이 조건은 행성을 상당히 강화하며 일반적으로 최소한 Own Sign 상태와 동등한 것으로 간주됩니다.`,} },
      { type: "paragraph", text: { en: `If a planet occupies its exaltation sign or own sign in both charts, its beneficial influence becomes even more powerful.`, hi: `यदि कोई ग्रह दोनों कुंडलियों में अपनी उच्च राशि या स्वराशि में हो तो उसका लाभकारी प्रभाव और भी अधिक शक्तिशाली हो जाता है।`, ja: `惑星が両方のチャートでその高揚サインまたは独自のサインを占める場合、その有益な影響はさらに強力になります。`, ko: `행성이 두 차트 모두에서 자신의 승영 별자리나 자체 별자리를 차지하면 그 유익한 영향력이 더욱 강력해집니다.`,} },
      { type: "heading", level: 3, text: { en: `Planetary War in Jyotish`, hi: `ज्योतिष में ग्रह युद्ध`, ja: `ジョーティッシュの惑星戦争`, ko: `Jyotish의 행성 전쟁`,} },
      { type: "paragraph", text: { en: `Planetary War occurs when two or more planets come into extremely close conjunction, usually within approximately one degree of each other.`, hi: `ग्रह युद्ध तब होता है जब दो या दो से अधिक ग्रह अत्यंत निकट संयोजन में आते हैं, आमतौर पर एक दूसरे के लगभग एक डिग्री के भीतर।`, ja: `惑星戦争は、2 つ以上の惑星が通常互いに約 1 度以内で非常に接近して結合するときに発生します。`, ko: `행성 전쟁은 두 개 이상의 행성이 일반적으로 서로 대략 1도 내에서 극도로 가까운 결합을 할 때 발생합니다.`,} },
      { type: "paragraph", text: { en: `Most Jyotish texts state that the planet at the lower degree wins the war, while the planet at the higher degree loses some of its ability to produce positive results.`, hi: `अधिकांश ज्योतिष ग्रंथों में कहा गया है कि निम्न डिग्री पर ग्रह युद्ध जीतता है, जबकि उच्च डिग्री पर ग्रह सकारात्मक परिणाम देने की अपनी कुछ क्षमता खो देता है।`, ja: `ジョーティッシュのテキストのほとんどは、低次数の惑星が戦争に勝つ一方、高次数の惑星は肯定的な結果を生み出す能力の一部を失うと述べています。`, ko: `대부분의 Jyotish 텍스트에는 낮은 등급의 행성이 전쟁에서 승리하는 반면, 높은 등급의 행성은 긍정적인 결과를 생성하는 능력의 일부를 잃는다고 명시되어 있습니다.`,} },
      { type: "paragraph", text: { en: `There is little doubt that planets positioned this closely together create significant effects. However, there remains considerable scholarly debate regarding the exact conditions required for Planetary War and the precise outcomes experienced by the planets involved.`, hi: `इसमें कोई संदेह नहीं है कि एक-दूसरे के करीब स्थित ग्रह महत्वपूर्ण प्रभाव पैदा करते हैं। हालाँकि, ग्रह युद्ध के लिए आवश्यक सटीक स्थितियों और इसमें शामिल ग्रहों द्वारा अनुभव किए गए सटीक परिणामों के बारे में काफी विद्वानों की बहस बनी हुई है।`, ja: `この近くに位置する惑星が重大な影響を生み出すことにほとんど疑いの余地はありません。しかし、惑星戦争に必要な正確な条件や、関与した惑星が経験した正確な結果については、学術的な議論がまだ残っています。`, ko: `이렇게 서로 밀접하게 위치하는 행성들이 상당한 효과를 만들어낸다는 것은 의심의 여지가 없습니다. 그러나 행성 전쟁에 필요한 정확한 조건과 관련된 행성이 경험하는 정확한 결과에 관한 상당한 학문적 논쟁이 남아 있습니다.`,} },
      { type: "paragraph", text: { en: `Note: The Sun, Moon, Rahu, and Ketu do not participate in Planetary War.`, hi: `नोट: सूर्य, चंद्रमा, राहु और केतु ग्रह युद्ध में भाग नहीं लेते हैं।`, ja: `注: 太陽、月、ラーフ、ケートゥは惑星戦争には参加しません。`, ko: `참고: 태양, 달, 라후, 케투는 행성 전쟁에 참여하지 않습니다.`,} },
    ],
  },
  {
    id: "chart-formats",
    section: "houses",
    title: { en: `Chart Formats in Jyotish Astrology`, hi: `ज्योतिष में चार्ट प्रारूप`, ja: `ジョーティッシュのチャート形式`, ko: `Jyotish 점성술의 차트 형식`,},
    related: ["twelve-houses","good-bad-houses","sidereal-zodiac-p3"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Chart Formats in Jyotish Astrology`, hi: `ज्योतिष में चार्ट प्रारूप`, ja: `ジョーティッシュのチャート形式`, ko: `Jyotish 점성술의 차트 형식`,} },
      { type: "paragraph", text: { en: `Summary: A comparison of the two primary birth-chart formats used in Jyotish Astrology—the North Indian and South Indian systems—along with suggested adaptations for students learning Jyotish. This overview is particularly useful for beginners seeking to understand and interpret Vedic astrology charts.`, hi: `सारांश: ज्योतिष में उपयोग किए जाने वाले दो प्राथमिक जन्म-चार्ट प्रारूपों की तुलना - उत्तर भारतीय और दक्षिण भारतीय प्रणाली - साथ ही ज्योतिष सीखने वाले छात्रों के लिए सुझाए गए अनुकूलन। यह अवलोकन वैदिक ज्योतिष चार्ट को समझने और व्याख्या करने के इच्छुक शुरुआती लोगों के लिए विशेष रूप से उपयोगी है।`, ja: `概要: ジョーティッシュで使用される 2 つの主要な出生図形式、北インド式と南インド式の比較と、ジョーティッシュを学習する学生向けに提案された適応方法。この概要は、ヴェーダ占星術のチャートを理解して解釈しようとしている初心者にとって特に役立ちます。`, ko: `요약: Jyotish 점성술에서 사용되는 두 가지 주요 출생 차트 형식(북인도 시스템과 남부 인도 시스템)을 Jyotish를 배우는 학생들을 위한 제안된 적응과 비교합니다. 이 개요는 베다 점성술 차트를 이해하고 해석하려는 초보자에게 특히 유용합니다.`,} },
      { type: "heading", level: 3, text: { en: `North Indian and South Indian Chart Formats Compared`, hi: `उत्तर भारतीय और दक्षिण भारतीय चार्ट प्रारूपों की तुलना`, ja: `北インドと南インドのチャート形式の比較`, ko: `북인도 및 남인도 차트 형식 비교`,} },
      { type: "paragraph", text: { en: `Most Western astrologers use a circular horoscope format, but this style of chart is not commonly used in Jyotish.`, hi: `अधिकांश पश्चिमी ज्योतिषी एक वृत्ताकार कुंडली प्रारूप का उपयोग करते हैं, लेकिन चार्ट की इस शैली का आमतौर पर ज्योतिष में उपयोग नहीं किया जाता है।`, ja: `ほとんどの西洋占星術師は円形ホロスコープ形式を使用しますが、この形式のチャートはジョーティッシュでは一般的に使用されません。`, ko: `대부분의 서양 점성가들은 원형 별자리 형식을 사용하지만 이러한 스타일의 차트는 Jyotish에서는 일반적으로 사용되지 않습니다.`,} },
      { type: "paragraph", text: { en: `In Vedic Astrology, there are two main chart formats: the North Indian system and the South Indian system. For newcomers to the subject, this can initially be confusing because the charts appear very different from one another. However, both formats display exactly the same astrological information—they simply present it in different ways.`, hi: `वैदिक ज्योतिष में, दो मुख्य चार्ट प्रारूप हैं: उत्तर भारतीय प्रणाली और दक्षिण भारतीय प्रणाली। विषय में नए लोगों के लिए, यह शुरू में भ्रमित करने वाला हो सकता है क्योंकि चार्ट एक दूसरे से बहुत अलग दिखाई देते हैं। हालाँकि, दोनों प्रारूप बिल्कुल एक जैसी ज्योतिषीय जानकारी प्रदर्शित करते हैं - वे बस इसे अलग-अलग तरीकों से प्रस्तुत करते हैं।`, ja: `ヴェーダ占星術には、北インド システムと南インド システムという 2 つの主要なチャート形式があります。このテーマの初心者にとって、グラフは互いに大きく異なって見えるため、最初は混乱する可能性があります。ただし、どちらの形式でもまったく同じ占星術情報が表示され、単に異なる方法で表示されます。`, ko: `베다 점성술에는 북인도 시스템과 남부 인도 시스템이라는 두 가지 주요 차트 형식이 있습니다. 이 주제를 처음 접하는 사람들에게는 차트가 서로 매우 다르게 나타나기 때문에 처음에는 혼란스러울 수 있습니다. 그러나 두 형식 모두 정확히 동일한 점성술 정보를 표시하며 단지 다른 방식으로 표시할 뿐입니다.`,} },
      { type: "paragraph", text: { en: `The diamond-shaped grid is predominantly used in North India, while the rectangular grid is more commonly used in South India. Both charts shown in the illustration below contain identical astrological data.`, hi: `हीरे के आकार की ग्रिड का उपयोग मुख्य रूप से उत्तर भारत में किया जाता है, जबकि आयताकार ग्रिड का उपयोग आमतौर पर दक्षिण भारत में किया जाता है। नीचे दिए गए चित्रण में दिखाए गए दोनों चार्ट में समान ज्योतिषीय डेटा शामिल है।`, ja: `ダイヤモンド型グリッドは主に北インドで使用され、長方形グリッドは南インドでより一般的に使用されます。以下の図に示されている両方のチャートには、同一の占星術データが含まれています。`, ko: `다이아몬드 모양의 격자는 인도 북부에서 주로 사용되는 반면, 직사각형 격자는 인도 남부에서 더 일반적으로 사용됩니다. 아래 그림에 표시된 두 차트에는 동일한 점성술 데이터가 포함되어 있습니다.`,} },
      { type: "paragraph", text: { en: `In the North Indian format, the Ascendant is always placed in the upper diamond-shaped section, and the zodiac signs are often numbered from 1 to 12, corresponding to Aries through Pisces. In the example horoscope shown, the Ascendant is in Pisces, the 12th sign, with both Jupiter and Venus positioned in the Ascendant. Rahu is located in Cancer, the 4th sign, which corresponds to the 5th house in this particular chart, and so on.`, hi: `उत्तर भारतीय प्रारूप में, लग्न को हमेशा ऊपरी हीरे के आकार के खंड में रखा जाता है, और राशि चक्र चिह्नों को अक्सर 1 से 12 तक गिना जाता है, जो मेष से मीन तक होता है। दिखाए गए उदाहरण कुंडली में, लग्न 12वीं राशि मीन में है, जिसमें बृहस्पति और शुक्र दोनों लग्न में स्थित हैं। राहु 4थी राशि कर्क में स्थित है, जो इस विशेष चार्ट में 5वें घर से मेल खाती है, इत्यादि।`, ja: `北インドの形式では、アセンダントは常に上部のひし形のセクションに配置され、星座には多くの場合、牡羊座から魚座に対応する 1 から 12 までの番号が付けられます。示されているホロスコープの例では、アセンダントは 12 番目の星座である魚座にあり、木星と金星の両方がアセンダントに位置しています。ラーフは、この特定のチャートでは 5 番目の家に対応する 4 番目の星座である蟹座に位置しています。`, ko: `북인도 형식에서 어센던트는 항상 위쪽 다이아몬드 모양 섹션에 배치되며, 황도대 별자리는 양자리에서 물고기자리에 해당하는 1부터 12까지 번호가 매겨지는 경우가 많습니다. 표시된 천궁도 예시에서 어센던트는 12번째 별자리인 물고기자리에 있으며 목성과 금성은 모두 어센던트에 위치합니다. Rahu는 이 특정 차트에서 5하우스에 해당하는 4번째 별자리인 게자리에 위치하고 있습니다.`,} },
      { type: "heading", level: 3, text: { en: `Comparison between North and South Indian Jyotish Chart Formats`, hi: `उत्तर और दक्षिण भारतीय ज्योतिष चार्ट प्रारूपों के बीच तुलना`, ja: `北インドと南インドのジョーティッシュ チャート形式の比較`, ko: `북부 인도와 남부 인도 Jyotish 차트 형식 비교`,} },
      eduImage(educationImages.chartFormatsComparison, {
        en: "Comparison between North Indian and South Indian chart formats", hi: "उत्तर भारतीय और दक्षिण भारतीय चार्ट प्रारूपों के बीच तुलना", ja: "北インド式と南インド式チャート形式の比較", ko: "북인도와 남인도 차트 형식 비교",
      }),
      { type: "paragraph", text: { en: `The zodiac signs used in Jyotish have the same names as those found in Western Astrology, such as Aries, Taurus, Gemini, and so forth. However, their actual positions in the sky differ from those used in Western astrology.`, hi: `ज्योतिष में प्रयुक्त राशियों के नाम वही हैं जो पश्चिमी ज्योतिष में पाए जाते हैं, जैसे मेष, वृषभ, मिथुन, इत्यादि। हालाँकि, आकाश में उनकी वास्तविक स्थिति पश्चिमी ज्योतिष में प्रयुक्त स्थितियों से भिन्न है।`, ja: `ジョーティッシュで使用される星座は、牡羊座、おうし座、双子座など、西洋占星術で見られるものと同じ名前です。ただし、実際の空の位置は西洋占星術で使用されるものとは異なります。`, ko: `Jyotish에서 사용되는 황도대 별자리는 양자리, 황소자리, 쌍둥이자리 등과 같이 서양 점성술에서 발견되는 것과 동일한 이름을 가지고 있습니다. 그러나 하늘에서의 실제 위치는 서양 점성술에서 사용되는 위치와 다릅니다.`,} },
      { type: "paragraph", text: { en: `This difference arises because Vedic Astrology references the zodiac signs against the background of the fixed stars and therefore uses the Sidereal Zodiac, whereas Western Astrology generally uses the Tropical Zodiac.`, hi: `यह अंतर इसलिए उत्पन्न होता है क्योंकि वैदिक ज्योतिष स्थिर सितारों की पृष्ठभूमि के विरुद्ध राशियों का संदर्भ देता है और इसलिए नाक्षत्र राशि चक्र का उपयोग करता है, जबकि पश्चिमी ज्योतिष आम तौर पर उष्णकटिबंधीय राशि चक्र का उपयोग करता है।`, ja: `この違いは、ヴェーダ占星術では恒星を背景に星座を参照するため恒星黄道帯を使用するのに対し、西洋占星術では一般的に熱帯黄道帯を使用するために生じます。`, ko: `이러한 차이는 베다 점성술이 고정된 별의 배경에 대한 황도대 별자리를 참조하여 항성 황도대를 사용하는 반면, 서양 점성술은 일반적으로 열대 황도대를 사용하기 때문에 발생합니다.`,} },
      { type: "paragraph", text: { en: `At present, there is approximately a 24-degree difference between these two systems. The Tropical Zodiac takes the Spring Equinox as the zero-degree reference point for Aries, but this reference gradually shifts against the fixed stars due to the phenomenon known as the precession of the equinoxes.`, hi: `वर्तमान में, इन दोनों प्रणालियों के बीच लगभग 24 डिग्री का अंतर है। उष्णकटिबंधीय राशि चक्र वसंत विषुव को मेष राशि के लिए शून्य-डिग्री संदर्भ बिंदु के रूप में लेता है, लेकिन विषुव की पूर्वता के रूप में जानी जाने वाली घटना के कारण यह संदर्भ धीरे-धीरे स्थिर सितारों के विरुद्ध स्थानांतरित हो जाता है।`, ja: `現在、これら 2 つのシステムの間には約 24 度の差があります。熱帯黄道帯は、春分点を牡羊座の 0 度の基準点としますが、この基準点は、春分点の歳差運動として知られる現象により、恒星に対して徐々に移動します。`, ko: `현재 이 두 시스템 사이에는 약 24도의 차이가 있습니다. 열대 황도대는 춘분점을 양자리의 0도 기준점으로 사용하지만, 이 기준점은 분점 세차 운동으로 알려진 현상으로 인해 고정된 별에 대해 점차적으로 이동합니다.`,} },
      { type: "paragraph", text: { en: `For those beginning their study of Jyotish, I believe a slightly modified version of the South Indian rectangular chart format is generally easier for Western students to understand and work with (see the diagram at the end of this article).`, hi: `ज्योतिष का अध्ययन शुरू करने वालों के लिए, मेरा मानना ​​​​है कि दक्षिण भारतीय आयताकार चार्ट प्रारूप का थोड़ा संशोधित संस्करण आमतौर पर पश्चिमी छात्रों के लिए समझना और काम करना आसान है (इस लेख के अंत में आरेख देखें)।`, ja: `ジョーティッシュの学習を始める人にとって、南インドの長方形チャート形式を少し修正したバージョンの方が、西洋の学生にとっては理解しやすく、扱いやすいと私は考えています (この記事の最後にある図を参照)。`, ko: `Jyotish 공부를 시작하는 사람들의 경우, 일반적으로 서양 학생들이 이해하고 작업하기 더 쉬운 남인도 직사각형 차트 형식의 약간 수정된 버전이 있다고 생각합니다(이 기사 마지막에 있는 다이어그램 참조).`,} },
      { type: "heading", level: 3, text: { en: `South Indian Jyotish Birth-chart Format`, hi: `दक्षिण भारतीय ज्योतिष जन्म-चार्ट प्रारूप`, ja: `南インドのジョーティッシュ出生図形式`, ko: `남부 인도 조티쉬 출생 차트 형식`,} },
      { type: "paragraph", text: { en: `In the South Indian chart system, each zodiac sign always occupies the same fixed position within the chart. For example, Pisces remains in the upper-left box, while Virgo always occupies the lower-right box.`, hi: `दक्षिण भारतीय चार्ट प्रणाली में, प्रत्येक राशि हमेशा चार्ट के भीतर एक ही निश्चित स्थान पर रहती है। उदाहरण के लिए, मीन राशि ऊपरी-बाएँ बॉक्स में रहती है, जबकि कन्या हमेशा निचले-दाएँ बॉक्स में रहती है।`, ja: `南インドのチャート システムでは、各星座は常にチャート内の同じ固定位置を占めます。たとえば、魚座は左上のボックスに残りますが、乙女座は常に右下のボックスを占めます。`, ko: `남부 인도 차트 시스템에서 각 황도대 별자리는 항상 차트 내에서 동일한 고정 위치를 차지합니다. 예를 들어 물고기자리는 왼쪽 위 상자에 남아 있고 처녀자리는 항상 오른쪽 아래 상자에 있습니다.`,} },
      { type: "paragraph", text: { en: `The zodiac signs are counted in a clockwise direction around the rectangular chart: Aries (1), Taurus (2), Gemini (3), Cancer (4), Leo (5), and so on.`, hi: `राशियों को आयताकार चार्ट के चारों ओर दक्षिणावर्त दिशा में गिना जाता है: मेष (1), वृषभ (2), मिथुन (3), कर्क (4), सिंह (5), इत्यादि।`, ja: `黄道十二宮は、長方形のチャートを中心に時計回りに数えられます。牡羊座 (1)、おうし座 (2)、双子座 (3)、蟹座 (4)、獅子座 (5) などです。`, ko: `황도대 별자리는 직사각형 차트를 중심으로 시계 방향으로 계산됩니다. 양자리(1), 황소자리(2), 쌍둥이자리(3), 게자리(4), 사자자리(5) 등입니다.`,} },
      { type: "paragraph", text: { en: `The Ascendant is indicated by a single diagonal line placed within the relevant sign. This remains the same regardless of the exact Ascendant degree. For example, an Ascendant at 1° Leo and an Ascendant at 29° Leo are both represented identically.`, hi: `लग्न को संबंधित चिह्न के भीतर स्थित एक विकर्ण रेखा द्वारा दर्शाया जाता है। सटीक लग्न डिग्री की परवाह किए बिना यह वही रहता है। उदाहरण के लिए, 1° सिंह पर एक लग्न और 29° सिंह पर एक लग्न दोनों को समान रूप से दर्शाया गया है।`, ja: `アセンダントは、関連するサイン内に配置された単一の対角線によって示されます。これは、正確なアセンダントの度数に関係なく同じままです。たとえば、獅子座 1 度のアセンダントと獅子座 29 度のアセンダントはどちらも同じように表されます。`, ko: `어센던트는 관련 기호 내에 배치된 단일 대각선으로 표시됩니다. 이는 정확한 승천 등급에 관계없이 동일하게 유지됩니다. 예를 들어 사자자리 1°의 어센던트와 사자자리 29°의 어센던트는 모두 동일하게 표시됩니다.`,} },
      { type: "paragraph", text: { en: `In this system, houses correspond exactly to signs and are counted clockwise from the Ascendant. Thus, if the Ascendant is in Leo—whether at 1 degree or 29 degrees—the entire sign of Leo becomes the 1st house, the whole sign of Virgo becomes the 2nd house, Libra becomes the 3rd house, and so forth.`, hi: `इस प्रणाली में, घर बिल्कुल संकेतों के अनुरूप होते हैं और लग्न से दक्षिणावर्त गिने जाते हैं। इस प्रकार, यदि लग्न सिंह राशि में है - चाहे 1 डिग्री या 29 डिग्री पर - सिंह की पूरी राशि पहला घर बन जाती है, कन्या की पूरी राशि दूसरा घर बन जाती है, तुला तीसरा घर बन जाती है, इत्यादि।`, ja: `このシステムでは、ハウスはサインに正確に対応し、アセンダントから時計回りに数えられます。したがって、アセンダントが獅子座にある場合、1度でも29度でも、獅子座全体が第1室となり、乙女座全体が第2室、天秤座が第3室、というようになります。`, ko: `이 시스템에서 하우스는 표지판과 정확하게 일치하며 어센던트를 기준으로 시계 방향으로 계산됩니다. 따라서 어센던트가 사자자리(1도든 29도든)에 있으면 사자자리 전체 별자리가 1하우스가 되고, 처녀자리 전체 별자리가 2하우스가 되고, 천칭자리가 3하우스가 되는 식입니다.`,} },
      { type: "heading", level: 3, text: { en: `South Indian Vedic Astrology Chart Format`, hi: `दक्षिण भारतीय वैदिक ज्योतिष चार्ट प्रारूप`, ja: `南インドのヴェーダ占星術チャートの形式`, ko: `남부 인도 베다 점성술 차트 형식`,} },
      eduImage(educationImages.southIndianChart, {
        en: "South Indian Vedic chart format", hi: "दक्षिण भारतीय वैदिक चार्ट प्रारूप", ja: "南インド式ヴェーダチャート形式", ko: "남부 인도 베다 차트 형식",
      }),
    ],
  },
  {
    id: "twelve-houses",
    section: "houses",
    title: { en: `The Twelve Houses and Their Indications`, hi: `बारह भाव और उनके संकेत`, ja: `12ハウスとその暗示`, ko: `열두 집과 그 표시`,},
    related: ["good-bad-houses","planetary-strengths","chart-formats"],
    blocks: [
      { type: "heading", level: 2, text: { en: `The Twelve Houses and Their Indications`, hi: `बारह भाव और उनके संकेत`, ja: `12ハウスとその暗示`, ko: `열두 집과 그 표시`,} },
      { type: "paragraph", text: { en: `Summary: Covers the primary indications of each of the Twelve Houses in Vedic Astrology, together with explanatory notes and House Classifications.`, hi: `सारांश: व्याख्यात्मक नोट्स और हाउस वर्गीकरण के साथ, वैदिक ज्योतिष में बारह घरों में से प्रत्येक के प्राथमिक संकेतों को शामिल किया गया है।`, ja: `概要: ヴェーダ占星術の各 12 ハウスの主な兆候を、説明メモとハウス分類とともに取り上げます。`, ko: `요약: 설명 메모 및 하우스 분류와 함께 베다 점성술의 각 12하우스의 주요 표시를 다룹니다.`,} },
      { type: "paragraph", text: { en: `This section is essential reading for students of Jyotish, as it outlines the principal areas of life governed by each of the twelve houses.`, hi: `यह खंड ज्योतिष के छात्रों के लिए आवश्यक है, क्योंकि यह बारह घरों में से प्रत्येक द्वारा शासित जीवन के प्रमुख क्षेत्रों की रूपरेखा तैयार करता है।`, ja: `このセクションは、12 ハウスのそれぞれが支配する生活の主な分野について概説しているため、ジョーティッシュの学生にとって必読の書です。`, ko: `이 섹션은 12하우스 각각이 관리하는 주요 삶의 영역을 개괄적으로 설명하므로 Jyotish 학생들이 꼭 읽어야 할 부분입니다.`,} },
      { type: "paragraph", text: { en: `Jyotish divides the 360 degrees of the sky into twelve equal sections, each measuring 30 degrees. These divisions create the twelve houses used in Vedic Astrology. Jyotish always employs the Sidereal Zodiac.`, hi: `ज्योतिष आकाश के 360 डिग्री को बारह बराबर खंडों में विभाजित करता है, जिनमें से प्रत्येक का माप 30 डिग्री है। ये विभाजन वैदिक ज्योतिष में प्रयुक्त बारह घरों का निर्माण करते हैं। ज्योतिष सदैव नक्षत्र राशि का प्रयोग करता है।`, ja: `ジョーティッシュは、空の 360 度を 30 度ずつ 12 等分に分割します。これらの区分は、ヴェーダ占星術で使用される 12 ハウスを作成します。ジョーティッシュは常に恒星黄道帯を採用します。`, ko: `Jyotish는 하늘의 360도를 각각 30도를 측정하는 12개의 동일한 섹션으로 나눕니다. 이러한 구분은 베다 점성술에 사용되는 12하우스를 만듭니다. Jyotish는 항상 Sidereal Zodiac을 사용합니다.`,} },
      { type: "paragraph", text: { en: `Each house governs specific areas of life. Further details regarding the primary significations of the houses can be found in the article The Twelve Houses. Most chart interpretations in Jyotish are based upon a house-by-house examination.`, hi: `प्रत्येक घर जीवन के विशिष्ट क्षेत्रों को नियंत्रित करता है। घरों के प्राथमिक महत्व के बारे में अधिक विवरण बारह सदनों के लेख में पाया जा सकता है। ज्योतिष में अधिकांश चार्ट व्याख्याएं घर-घर जांच पर आधारित होती हैं।`, ja: `各ハウスは生活の特定の領域を統治します。ハウスの主な意味に関する詳細については、「The Twelve Houses」の記事を参照してください。ジョーティッシュにおけるほとんどのチャート解釈は、ハウスごとの検査に基づいています。`, ko: `각 집은 삶의 특정 영역을 관리합니다. 집의 주요 의미에 관한 더 자세한 내용은 The Twelve Houses 기사에서 찾아볼 수 있습니다. Jyotish의 대부분의 차트 해석은 집별 조사를 기반으로 합니다.`,} },
      { type: "image", src: "/assets/001.jpeg", alt: { en: `Equal House diagram in Jyotish`, hi: `ज्योतिष में समान घर का आरेख`, ja: `ジョーティッシュのイコールハウス図`, ko: `Jyotish의 Equal House 다이어그램`,} },
      { type: "paragraph", text: { en: `Most chart interpretations are conducted on a house-by-house basis, making a sound understanding of the houses and their indications absolutely essential.`, hi: `अधिकांश चार्ट व्याख्याएँ घर-दर-घर के आधार पर की जाती हैं, जिससे घरों और उनके संकेतों की अच्छी समझ बिल्कुल आवश्यक हो जाती है।`, ja: `チャートの解釈のほとんどはハウスごとに行われるため、ハウスとその指標をしっかりと理解することが不可欠です。`, ko: `대부분의 차트 해석은 주택별로 수행되므로 주택과 해당 표시에 대한 올바른 이해가 절대적으로 중요합니다.`,} },
      { type: "paragraph", text: { en: `Traditional Jyotish texts often provide extensive lists of matters associated with each house. However, in this article, I have attempted to remain concise and focus on the most important indications.`, hi: `पारंपरिक ज्योतिष ग्रंथ अक्सर प्रत्येक घर से जुड़े मामलों की विस्तृत सूची प्रदान करते हैं। हालाँकि, इस लेख में, मैंने संक्षिप्त रहने और सबसे महत्वपूर्ण संकेतों पर ध्यान केंद्रित करने का प्रयास किया है।`, ja: `伝統的なジョーティッシュのテキストには、各家に関連する事項の広範なリストが記載されていることがよくあります。ただし、この記事では簡潔さを保ち、最も重要な兆候に焦点を当てるように努めました。`, ko: `전통적인 Jyotish 텍스트는 종종 각 집과 관련된 문제의 광범위한 목록을 제공합니다. 그러나 이 기사에서는 간결함을 유지하고 가장 중요한 징후에 초점을 맞추려고 노력했습니다.`,} },
      { type: "heading", level: 3, text: { en: `First House – ‘House of Body’`, hi: `प्रथम भाव - 'शरीर का भाव'`, ja: `最初の家 – 「身体の家」`, ko: `첫 번째 집 - '몸의 집'`,} },
      { type: "heading", level: 3, text: { en: `House Indications:`, hi: `घर के संकेत:`, ja: `ハウスの表示:`, ko: `주택 표시:`,} },
      { type: "paragraph", text: { en: `• Birth and early childhood`, hi: `• जन्म और प्रारंभिक बचपन`, ja: `• 誕生と幼少期`, ko: `• 출생과 유아기`,} },
      { type: "paragraph", text: { en: `• Health, physical body, and vitality`, hi: `• स्वास्थ्य, भौतिक शरीर और जीवन शक्ति`, ja: `・健康、肉体、活力`, ko: `• 건강, 육체, 활력`,} },
      { type: "paragraph", text: { en: `• Personality and temperament`, hi: `• व्यक्तित्व एवं स्वभाव`, ja: `• 性格と気質`, ko: `• 성격과 기질`,} },
      { type: "paragraph", text: { en: `• Self-confidence and self-esteem`, hi: `• आत्मविश्वास और आत्म-सम्मान`, ja: `• 自信と自尊心`, ko: `• 자신감과 자부심`,} },
      { type: "paragraph", text: { en: `• Prosperity and fame`, hi: `• समृद्धि और प्रसिद्धि`, ja: `• 繁栄と名声`, ko: `• 번영과 명성`,} },
      { type: "paragraph", text: { en: `• Dharma – actions and activities that promote spiritual evolution`, hi: `• धर्म - कार्य और गतिविधियां जो आध्यात्मिक विकास को बढ़ावा देती हैं`, ja: `• ダルマ – 霊的進化を促進する行動と活動`, ko: `• 달마(Dharma) – 영적 진화를 촉진하는 행동과 활동`,} },
      { type: "paragraph", text: { en: `The 1st house governs several key areas of life, and a strong [1] first house tends to improve the overall quality of the horoscope.`, hi: `पहला घर जीवन के कई प्रमुख क्षेत्रों को नियंत्रित करता है, और एक मजबूत [1] पहला घर कुंडली की समग्र गुणवत्ता में सुधार करता है।`, ja: `第 1 ハウスは人生のいくつかの重要な領域を支配しており、強い [1] の第 1 ハウスはホロスコープ全体の質を向上させる傾向があります。`, ko: `1하우스는 삶의 여러 주요 영역을 관장하며, 강력한 [1] 1하우스는 별자리의 전반적인 품질을 향상시키는 경향이 있습니다.`,} },
      { type: "paragraph", text: { en: `It represents the self and all matters connected with our identity. The ruler of the 1st house plays a major role in shaping our personality, behaviour, and natural tendencies.`, hi: `यह स्वयं और हमारी पहचान से जुड़े सभी मामलों का प्रतिनिधित्व करता है। प्रथम भाव का स्वामी हमारे व्यक्तित्व, व्यवहार और प्राकृतिक प्रवृत्तियों को आकार देने में प्रमुख भूमिका निभाता है।`, ja: `それは自己と、私たちのアイデンティティに関連するすべての事項を表します。第 1 ハウスの支配者は、私たちの性格、行動、自然な傾向の形成に大きな役割を果たします。`, ko: `그것은 자아와 우리의 정체성과 관련된 모든 문제를 나타냅니다. 1하우스의 통치자는 우리의 성격, 행동, 타고난 성향을 형성하는 데 중요한 역할을 합니다.`,} },
      { type: "paragraph", text: { en: `House Classification: Kendra / Dharma (Angular House / Action)`, hi: `गृह वर्गीकरण: केंद्र/धर्म (कोणीय गृह/क्रिया)`, ja: `ハウス分類: ケンドラ / ダーマ (角のあるハウス / アクション)`, ko: `하우스 분류: Kendra / Dharma(앵귤러 하우스 / 액션)`,} },
      { type: "paragraph", text: { en: `House Indicator [2]: Sun`, hi: `गृह सूचक [2]: सूर्य`, ja: `ハウスインジケーター [2]: 太陽`, ko: `하우스 표시기 [2]: 태양`,} },
      { type: "heading", level: 3, text: { en: `Second House – ‘House of Wealth’`, hi: `दूसरा घर - 'धन का घर'`, ja: `セカンドハウス – 「富の家」`, ko: `두 번째 집 - '부의 집'`,} },
      { type: "heading", level: 3, text: { en: `House Indications:`, hi: `घर के संकेत:`, ja: `ハウスの表示:`, ko: `주택 표시:`,} },
      { type: "paragraph", text: { en: `• Accumulated wealth and finances`, hi: `• संचित धन और वित्त`, ja: `• 蓄積された富と財政`, ko: `• 축적된 부와 재정`,} },
      { type: "paragraph", text: { en: `• Speech and verbal communication`, hi: `• वाणी और मौखिक संचार`, ja: `• スピーチと口頭コミュニケーション`, ko: `• 말하기 및 언어적 의사소통`,} },
      { type: "paragraph", text: { en: `• Family life`, hi: `• पारिवारिक जीवन`, ja: `• 家族生活`, ko: `• 가족생활`,} },
      { type: "paragraph", text: { en: `The 2nd house is the principal indicator of the wealth and financial resources we accumulate throughout life.`, hi: `दूसरा भाव जीवन भर हमारे द्वारा अर्जित धन और वित्तीय संसाधनों का प्रमुख संकेतक है।`, ja: `2ハウスは、私たちが生涯を通じて蓄積する富と財源の主な指標です。`, ko: `2하우스는 우리가 일생 동안 축적한 부와 재정 자원을 나타내는 주요 지표입니다.`,} },
      { type: "paragraph", text: { en: `It is also closely associated with speech and verbal expression, making it important in matters relating to education and communication.`, hi: `यह भाषण और मौखिक अभिव्यक्ति से भी निकटता से जुड़ा हुआ है, जो इसे शिक्षा और संचार से संबंधित मामलों में महत्वपूर्ण बनाता है।`, ja: `また、スピーチや言語表現とも密接に関連しているため、教育やコミュニケーションに関連する問題において重要です。`, ko: `또한 말하기 및 언어 표현과도 밀접하게 연관되어 있어 교육 및 의사소통과 관련된 문제에서 중요합니다.`,} },
      { type: "paragraph", text: { en: `House Classification: Artha (Wealth)`, hi: `मकान वर्गीकरण: अर्थ (धन)`, ja: `ハウス分類: Artha (富裕層)`, ko: `주택 분류: Artha(부)`,} },
      { type: "paragraph", text: { en: `House Indicator: Jupiter`, hi: `गृह सूचक: बृहस्पति`, ja: `ハウスインジケーター: 木星`, ko: `하우스 표시기: 목성`,} },
      { type: "heading", level: 3, text: { en: `Third House – ‘House of Brothers, Sisters and Desires’`, hi: `तीसरा घर - 'भाइयों, बहनों और इच्छाओं का घर'`, ja: `第三の家 – 「兄弟、姉妹、そして欲望の家」`, ko: `세 번째 집 - '형제, 자매, 욕망의 집'`,} },
      { type: "heading", level: 3, text: { en: `House Indications:`, hi: `घर के संकेत:`, ja: `ハウスの表示:`, ko: `주택 표시:`,} },
      { type: "paragraph", text: { en: `• Brothers and sisters`, hi: `• भाइयों और बहनों`, ja: `• 兄弟姉妹`, ko: `• 형제자매들`,} },
      { type: "paragraph", text: { en: `• Desires and ambitions`, hi: `• इच्छाएँ और महत्त्वाकांक्षाएँ`, ja: `• 願望と野心`, ko: `• 욕망과 야망`,} },
      { type: "paragraph", text: { en: `• Courage`, hi: `• साहस`, ja: `• 勇気`, ko: `• 용기`,} },
      { type: "paragraph", text: { en: `• Personal effort and initiative`, hi: `• व्यक्तिगत प्रयास और पहल`, ja: `• 個人の努力と自発性`, ko: `• 개인적인 노력과 이니셔티브`,} },
      { type: "paragraph", text: { en: `• Communication`, hi: `• संचार`, ja: `• コミュニケーション`, ko: `• 의사소통`,} },
      { type: "paragraph", text: { en: `A favourable 3rd house brings happiness through brothers and sisters. Siblings may be supportive and beneficial, and relationships with them are often harmonious. Some astrologers restrict the indications of the 3rd house specifically to younger siblings.`, hi: `अनुकूल तृतीय भाव भाइयों और बहनों के माध्यम से खुशी लाता है। भाई-बहन सहायक और लाभकारी हो सकते हैं, और उनके साथ संबंध अक्सर सामंजस्यपूर्ण होते हैं। कुछ ज्योतिषी तीसरे घर के संकेतों को विशेष रूप से छोटे भाई-बहनों तक सीमित रखते हैं।`, ja: `有利な3ハウスは兄弟姉妹を通じて幸福をもたらします。兄弟姉妹は協力的で有益な場合があり、兄弟関係はしばしば調和が取れています。一部の占星術師は、3 ハウスの表示を特に若い兄弟に限定しています。`, ko: `유리한 3하우스는 형제자매를 통해 행복을 가져다줍니다. 형제자매는 지지적이고 유익할 수 있으며 그들과의 관계는 대개 조화롭습니다. 일부 점성가들은 3하우스 표시를 특히 동생들에게만 제한합니다.`,} },
      { type: "paragraph", text: { en: `The 3rd is an Upachaya, or "growing" house, where malefic planets [4] generally perform well unless debilitated or otherwise weakened.`, hi: `तीसरा एक उपचय, या "बढ़ता हुआ" घर है, जहां अशुभ ग्रह [4] आम तौर पर अच्छा प्रदर्शन करते हैं जब तक कि वे दुर्बल या अन्यथा कमजोर न हों।`, ja: `3 番目はウパチャヤ、または「成長する」ハウスで、ここでは凶星 [4] が衰弱したり弱体化したりしない限り、一般に良好なパフォーマンスを示します。`, ko: `세 번째는 Upachaya 또는 "성장하는" 하우스로, 흉성 행성[4]이 쇠약해지거나 약화되지 않는 한 일반적으로 잘 수행됩니다.`,} },
      { type: "paragraph", text: { en: `House Classification: Upachaya / Kama (Growing House / Desire)`, hi: `मकान का वर्गीकरण: उपचय/काम (बढ़ता मकान/इच्छा)`, ja: `ハウス分類: ウパチャヤ / カマ (成長する家 / 欲望)`, ko: `주택 분류: 우파차야/카마(성장하는 집/욕망)`,} },
      { type: "paragraph", text: { en: `House Indicator: Mars`, hi: `गृह सूचक: मंगल`, ja: `ハウスインジケーター: 火星`, ko: `하우스 표시기: 화성`,} },
      { type: "heading", level: 3, text: { en: `Fourth House – ‘House of Happiness and Comforts’`, hi: `चौथा घर - 'खुशी और आराम का घर'`, ja: `第 4 の家 – 「幸福と安らぎの家」`, ko: `네 번째 집 - '행복과 편안함의 집'`,} },
      { type: "heading", level: 3, text: { en: `House Indications:`, hi: `घर के संकेत:`, ja: `ハウスの表示:`, ko: `주택 표시:`,} },
      { type: "paragraph", text: { en: `• Happiness and comforts`, hi: `• ख़ुशी और आराम`, ja: `• 幸福と快適さ`, ko: `• 행복과 편안함`,} },
      { type: "paragraph", text: { en: `• The affairs, well-being, and relationship with our mother`, hi: `• हमारी माँ के साथ मामले, भलाई और संबंध`, ja: `• 事情、幸福、そして母親との関係`, ko: `• 어머니와의 일, 안녕, 관계`,} },
      { type: "paragraph", text: { en: `• Fixed assets such as property, land, and buildings`, hi: `• अचल संपत्तियां जैसे संपत्ति, भूमि और भवन`, ja: `• 不動産、土地、建物などの固定資産`, ko: `• 부동산, 토지, 건물 등 고정자산`,} },
      { type: "paragraph", text: { en: `• Friends and relatives`, hi: `• दोस्त और रिश्तेदार`, ja: `• 友人や親戚`, ko: `• 친구 및 친척`,} },
      { type: "paragraph", text: { en: `The 4th house governs the home environment and our mother. The condition of the Moon also provides important information regarding the mother's well-being.`, hi: `चतुर्थ भाव घर के वातावरण और हमारी माँ को नियंत्रित करता है। चंद्रमा की स्थिति माता के स्वास्थ्य के संबंध में भी महत्वपूर्ण जानकारी प्रदान करती है।`, ja: `4ハウスは家庭環境と母親を支配します。月の状態は、母親の健康に関する重要な情報も提供します。`, ko: `4하우스는 가정 환경과 어머니를 관리합니다. 달의 상태는 또한 산모의 안녕에 관한 중요한 정보를 제공합니다.`,} },
      { type: "paragraph", text: { en: `This house reflects our overall level of happiness, contentment, and satisfaction in life, whether physical, emotional, spiritual, or financial.`, hi: `यह भाव हमारे जीवन में खुशी, संतुष्टि और संतुष्टि के समग्र स्तर को दर्शाता है, चाहे वह शारीरिक, भावनात्मक, आध्यात्मिक या वित्तीय हो।`, ja: `この家は、身体的、感情的、精神的、経済的など、人生における幸福、満足感、満足度の全体的なレベルを反映しています。`, ko: `이 집은 신체적, 정서적, 영적, 재정적 등 삶의 전반적인 행복, 만족 ​​및 만족 수준을 반영합니다.`,} },
      { type: "paragraph", text: { en: `House Classification: Kendra / Moksha (Angular / Liberation)`, hi: `गृह वर्गीकरण: केंद्र/मोक्ष (कोणीय/मुक्ति)`, ja: `ハウス分類: ケンドラ / モクシャ (角度 / 解放)`, ko: `하우스 분류: Kendra / Moksha(Angular / Liberation)`,} },
      { type: "paragraph", text: { en: `House Indicator: Moon`, hi: `गृह सूचक: चंद्रमा`, ja: `ハウスインジケーター: 月`, ko: `하우스 인디케이터: 달`,} },
      { type: "heading", level: 3, text: { en: `Fifth House – ‘House of Children’`, hi: `पांचवां घर - 'बच्चों का घर'`, ja: `フィフスハウス – 「子どもの家」`, ko: `다섯 번째 집 - '어린이의 집'`,} },
      { type: "heading", level: 3, text: { en: `House Indications:`, hi: `घर के संकेत:`, ja: `ハウスの表示:`, ko: `주택 표시:`,} },
      { type: "paragraph", text: { en: `• Children, intelligence, education, and the mind`, hi: `• बच्चे, बुद्धि, शिक्षा और मन`, ja: `• 子供、知性、教育、そして精神`, ko: `• 어린이, 지능, 교육 및 정신`,} },
      { type: "paragraph", text: { en: `• Spiritual practices and religious knowledge`, hi: `• आध्यात्मिक अभ्यास और धार्मिक ज्ञान`, ja: `• 精神的な実践と宗教的知識`, ko: `• 영적 실천과 종교적 지식`,} },
      { type: "paragraph", text: { en: `• Past-life credit (positive returning karmas)`, hi: `• पिछले जीवन का श्रेय (सकारात्मक लौटने वाले कर्म)`, ja: `• 過去生のクレジット（ポジティブに戻ってくるカルマ）`, ko: `• 전생 크레딧(긍정적인 반환 카르마)`,} },
      { type: "paragraph", text: { en: `• Investment and speculation`, hi: `• निवेश और अटकलें`, ja: `• 投資と投機`, ko: `• 투자와 투기`,} },
      { type: "paragraph", text: { en: `The 5th house rules children and provides information regarding offspring, their number, and the happiness they bring into our lives.`, hi: `5वां घर बच्चों पर शासन करता है और संतान, उनकी संख्या और उनके द्वारा हमारे जीवन में आने वाली खुशियों के बारे में जानकारी प्रदान करता है।`, ja: `5室は子供を支配し、子孫、その数、そして彼らが私たちの生活にもたらす幸福に関する情報を提供します。`, ko: `5하우스는 아이들을 다스리며 자손, 숫자, 그들이 우리 삶에 가져오는 행복에 관한 정보를 제공합니다.`,} },
      { type: "paragraph", text: { en: `It also governs intelligence, common sense, learning ability, and education.`, hi: `यह बुद्धि, सामान्य ज्ञान, सीखने की क्षमता और शिक्षा को भी नियंत्रित करता है।`, ja: `また、知性、常識、学習能力、教育も司ります。`, ko: `또한 지능, 상식, 학습 능력 및 교육을 관리합니다.`,} },
      { type: "paragraph", text: { en: `A strong 5th house is frequently found in the charts of virtuous individuals who have made significant spiritual or personal progress.`, hi: `एक मजबूत 5वां घर अक्सर उन गुणी व्यक्तियों के चार्ट में पाया जाता है जिन्होंने महत्वपूर्ण आध्यात्मिक या व्यक्तिगत प्रगति की है।`, ja: `強力な 5 ハウスは、精神的または個人的に重要な進歩を遂げた高潔な個人のチャートによく見られます。`, ko: `강력한 5하우스는 정신적으로나 개인적으로 상당한 발전을 이룬 덕망 있는 개인의 차트에서 자주 발견됩니다.`,} },
      { type: "paragraph", text: { en: `The 5th is considered a highly auspicious house, and planets occupying it generally benefit from the placement.`, hi: `5वें स्थान को अत्यधिक शुभ घर माना जाता है और इस पर स्थित ग्रहों को आम तौर पर इस स्थान से लाभ होता है।`, ja: `5 番目は非常に縁起の良いハウスと考えられており、そこに位置する惑星は一般にその配置から恩恵を受けます。`, ko: `5하우스는 매우 상서로운 하우스로 간주되며, 이 하우스를 차지하는 행성은 일반적으로 배치로 인해 이익을 얻습니다.`,} },
      { type: "paragraph", text: { en: `House Classification: Trikona / Dharma (Trinal / Action)`, hi: `घर का वर्गीकरण: त्रिकोण / धर्म (त्रिनल / क्रिया)`, ja: `ハウス分類: トリコナ / ダルマ (トリナル / アクション)`, ko: `하우스 분류: Trikona / Dharma(Trinal / Action)`,} },
      { type: "paragraph", text: { en: `House Indicator: Jupiter`, hi: `गृह सूचक: बृहस्पति`, ja: `ハウスインジケーター: 木星`, ko: `하우스 표시기: 목성`,} },
      { type: "heading", level: 3, text: { en: `Sixth House – ‘House of Enemies’`, hi: `छठा घर - 'शत्रुओं का घर'`, ja: `第 6 ハウス – 「敵の家」`, ko: `여섯 번째 집 - '적의 집'`,} },
      { type: "heading", level: 3, text: { en: `House Indications:`, hi: `घर के संकेत:`, ja: `ハウスの表示:`, ko: `주택 표시:`,} },
      { type: "paragraph", text: { en: `• Enemies, competitors, jealous individuals, work subordinates, and obstacles`, hi: `• शत्रु, प्रतिस्पर्धी, ईर्ष्यालु व्यक्ति, कार्य अधीनस्थ, और बाधाएँ`, ja: `• 敵、競争相手、嫉妬深い人、仕事の部下、障害物`, ko: `• 적, 경쟁사, 질투하는 개인, 직장 부하 직원 및 장애물`,} },
      { type: "paragraph", text: { en: `• Illness and disease`, hi: `• बीमारी और रोग`, ja: `• 病気と疾病`, ko: `• 질병 및 질환`,} },
      { type: "paragraph", text: { en: `• Worries and anxieties`, hi: `• चिंताएँ और चिन्ताएँ`, ja: `• 心配や不安`, ko: `• 걱정과 불안`,} },
      { type: "paragraph", text: { en: `In this context, "enemies" can include competitors or people who may rise to a higher status than us within an organisation.`, hi: `इस संदर्भ में, "शत्रुओं" में प्रतिस्पर्धी या ऐसे लोग शामिल हो सकते हैं जो किसी संगठन में हमसे ऊंचे पद तक पहुंच सकते हैं।`, ja: `この文脈での「敵」には、競合他社や、組織内で私たちよりも高い地位に昇進する可能性のある人々が含まれる場合があります。`, ko: `이러한 맥락에서 "적"에는 조직 내에서 우리보다 더 높은 지위에 오를 수 있는 경쟁자나 사람들이 포함될 수 있습니다.`,} },
      { type: "paragraph", text: { en: `A powerful 6th house often enables a person to excel and reach the top of their chosen profession.`, hi: `एक शक्तिशाली छठा घर अक्सर व्यक्ति को अपने चुने हुए पेशे में उत्कृष्टता प्राप्त करने और शीर्ष पर पहुंचने में सक्षम बनाता है।`, ja: `強力な6ハウスは、多くの場合、人が優れた能力を発揮し、選択した職業のトップに到達することを可能にします。`, ko: `강력한 6하우스는 종종 사람이 자신이 선택한 직업에서 탁월하고 최고에 도달할 수 있게 해줍니다.`,} },
      { type: "paragraph", text: { en: `The 6th is another Upachaya or growing house, meaning that the problems it indicates can improve with time. For example, a health issue shown by the 6th house may be present during childhood but disappear later in life.`, hi: `छठा एक और उपचय या बढ़ता हुआ घर है, जिसका अर्थ है कि यह जिन समस्याओं का संकेत देता है उनमें समय के साथ सुधार हो सकता है। उदाहरण के लिए, छठे घर द्वारा दिखाई गई स्वास्थ्य समस्या बचपन के दौरान मौजूद हो सकती है लेकिन बाद में जीवन में गायब हो जाती है।`, ja: `6番目は、別のウパチャヤまたは成長する家であり、それが示す問題は時間の経過とともに改善される可能性があることを意味します。たとえば、6 ハウスによって示される健康上の問題は、幼少期に存在する可能性がありますが、人生の後半には消失します。`, ko: `6번째는 또 다른 우파차야(Upachaya) 또는 성장하는 집입니다. 이는 그것이 나타내는 문제가 시간이 지남에 따라 개선될 수 있음을 의미합니다. 예를 들어, 6하우스에 나타나는 건강 문제는 어린 시절에 나타났다가 나중에 사라질 수 있습니다.`,} },
      { type: "paragraph", text: { en: `Malefic planets and their natural significations generally function reasonably well in the 6th house.`, hi: `अशुभ ग्रह और उनके प्राकृतिक प्रभाव आम तौर पर छठे घर में काफी अच्छी तरह से कार्य करते हैं।`, ja: `凶星とその自然の意味は、一般的に 6 室で適度に機能します。`, ko: `흉성 행성과 그 자연적 의미는 일반적으로 6하우스에서 합리적으로 잘 기능합니다.`,} },
      { type: "paragraph", text: { en: `However, the houses ruled by planets occupying the 6th are often disturbed to some extent.`, hi: `हालाँकि, छठे स्थान पर स्थित ग्रहों द्वारा शासित घर अक्सर कुछ हद तक परेशान रहते हैं।`, ja: `ただし、6番目に位置する惑星が支配するハウスは、ある程度乱れることがよくあります。`, ko: `그러나 6번째 행성이 ​​지배하는 하우스는 어느 정도 교란되는 경우가 많습니다.`,} },
      { type: "paragraph", text: { en: `House Classification: Dusthana / Upachaya / Artha (Negative / Growing / Wealth)`, hi: `मकान का वर्गीकरण: दुस्थान / उपचय / अर्थ (नकारात्मक / वृद्धि / धन)`, ja: `ハウス分類: ダスターナ / ウパチャヤ / アルタ (ネガティブ / 成長 / 富)`, ko: `주택 분류: Dusthana / Upachaya / Artha(부정적 / 성장 / 부)`,} },
      { type: "paragraph", text: { en: `House Indicator: Mars`, hi: `गृह सूचक: मंगल`, ja: `ハウスインジケーター: 火星`, ko: `하우스 표시기: 화성`,} },
      { type: "heading", level: 3, text: { en: `Seventh House – ‘House of Marriage and Partnerships’`, hi: `सातवां घर - 'विवाह और साझेदारी का घर'`, ja: `7番目の家 – 「結婚とパートナーシップの家」`, ko: `일곱 번째 집 - '결혼과 파트너십의 집'`,} },
      { type: "heading", level: 3, text: { en: `House Indications:`, hi: `घर के संकेत:`, ja: `ハウスの表示:`, ko: `주택 표시:`,} },
      { type: "paragraph", text: { en: `• Marriage and married life`, hi: `• विवाह और वैवाहिक जीवन`, ja: `• 結婚と結婚生活`, ko: `• 결혼과 결혼생활`,} },
      { type: "paragraph", text: { en: `• Spouse or partner`, hi: `• जीवनसाथी या साथी`, ja: `• 配偶者またはパートナー`, ko: `• 배우자 또는 파트너`,} },
      { type: "paragraph", text: { en: `• Sexual passions`, hi: `• यौन जुनून`, ja: `• 性的情熱`, ko: `• 성적 열정`,} },
      { type: "paragraph", text: { en: `• Partnerships of all kinds, including business partnerships`, hi: `• व्यावसायिक साझेदारियों सहित सभी प्रकार की साझेदारियाँ`, ja: `• ビジネスパートナーシップを含むあらゆる種類のパートナーシップ`, ko: `• 비즈니스 파트너십을 포함한 모든 종류의 파트너십`,} },
      { type: "paragraph", text: { en: `The 7th house reveals the quality of married life and the well-being of one's partner.`, hi: `7वां घर वैवाहिक जीवन की गुणवत्ता और किसी के साथी की भलाई को प्रकट करता है।`, ja: `7 ハウスは、結婚生活の質とパートナーの幸福を示します。`, ko: `7하우스는 결혼 생활의 질과 파트너의 행복을 드러냅니다.`,} },
      { type: "paragraph", text: { en: `Additional insights regarding marriage can be obtained by treating the Moon's sign as the Ascendant and examining the planets located in the 7th house from the Moon.`, hi: `चंद्रमा की राशि को लग्न मानकर और चंद्रमा से सातवें घर में स्थित ग्रहों की जांच करके विवाह के संबंध में अतिरिक्त जानकारी प्राप्त की जा सकती है।`, ja: `結婚に関するさらなる洞察は、月の星座をアセンダントとして扱い、月から7番目の家に位置する惑星を調べることによって得ることができます。`, ko: `결혼에 관한 추가적인 통찰력은 달의 별자리를 승천자로 취급하고 달에서 7하우스에 위치한 행성을 조사함으로써 얻을 수 있습니다.`,} },
      { type: "paragraph", text: { en: `A strong Navamsa chart [5] is highly beneficial for relationships and marriage.`, hi: `एक मजबूत नवांश कुंडली [5] रिश्तों और विवाह के लिए अत्यधिक फायदेमंद है।`, ja: `強力なナヴァムサ チャート [5] は、恋愛や結婚に非常に有益です。`, ko: `강력한 Navamsa 차트[5]는 관계와 결혼에 매우 유익합니다.`,} },
      { type: "paragraph", text: { en: `The 7th house also governs certain aspects of travel.`, hi: `7वां घर यात्रा के कुछ पहलुओं को भी नियंत्रित करता है।`, ja: `7 ハウスは旅行の特定の側面も支配します。`, ko: `7하우스는 여행의 특정 측면도 관장합니다.`,} },
      { type: "paragraph", text: { en: `House Classification: Kendra / Kama (Angular / Desire)`, hi: `गृह वर्गीकरण: केंद्र/काम (कोणीय/इच्छा)`, ja: `ハウス分類: ケンドラ / カマ (角度 / 欲望)`, ko: `주택 분류: Kendra / Kama(Angular / Desire)`,} },
      { type: "paragraph", text: { en: `House Indicator: Venus`, hi: `गृह सूचक: शुक्र`, ja: `ハウスインジケーター: 金星`, ko: `하우스 인디케이터: 금성`,} },
      { type: "heading", level: 3, text: { en: `Eighth House – ‘House of Transformation’`, hi: `आठवां घर - 'परिवर्तन का घर'`, ja: `第8ハウス – 「変革の家」`, ko: `여덟 번째 집 - '변형의 집'`,} },
      { type: "heading", level: 3, text: { en: `House Indications:`, hi: `घर के संकेत:`, ja: `ハウスの表示:`, ko: `주택 표시:`,} },
      { type: "paragraph", text: { en: `• Life, longevity, and death`, hi: `• जीवन, दीर्घायु और मृत्यु`, ja: `• 生命、長寿、そして死`, ko: `• 삶, 장수, 죽음`,} },
      { type: "paragraph", text: { en: `• Wills, inheritances, and legacies`, hi: `• वसीयत, विरासत और विरासत`, ja: `• 遺言、相続、遺産`, ko: `• 유언장, 상속, 유산`,} },
      { type: "paragraph", text: { en: `• Intuition, occult studies, and hidden knowledge`, hi: `• अंतर्ज्ञान, गुप्त अध्ययन और छिपा हुआ ज्ञान`, ja: `• 直感、オカルト研究、隠された知識`, ko: `• 직관, 오컬트 연구, 숨겨진 지식`,} },
      { type: "paragraph", text: { en: `• Secret and esoteric subjects`, hi: `• गुप्त एवं गूढ़ विषय`, ja: `• 秘密および難解な主題`, ko: `• 비밀스럽고 난해한 주제`,} },
      { type: "paragraph", text: { en: `The 8th house is often referred to as the "House of Death" because it governs the nature and circumstances surrounding death.`, hi: `आठवें घर को अक्सर "मृत्यु का घर" कहा जाता है क्योंकि यह मृत्यु के आसपास की प्रकृति और परिस्थितियों को नियंत्रित करता है।`, ja: `8 ハウスは、死を取り巻く性質や状況を支配するため、「死の家」と呼ばれることがあります。`, ko: `8하우스는 죽음을 둘러싼 성격과 상황을 관장하기 때문에 종종 "죽음의 하우스"라고 불립니다.`,} },
      { type: "paragraph", text: { en: `However, a strong 8th house, particularly when supported by a well-placed Saturn, can indicate a long, active, and energetic life.`, hi: `हालाँकि, एक मजबूत आठवां घर, खासकर जब एक अच्छी तरह से स्थित शनि द्वारा समर्थित हो, एक लंबे, सक्रिय और ऊर्जावान जीवन का संकेत दे सकता है।`, ja: `しかし、強い 8 ハウスは、特に適切な位置にある土星にサポートされている場合、長く、活動的で、エネルギッシュな人生を示す可能性があります。`, ko: `그러나 강한 8하우스는 특히 잘 배치된 토성이 지탱할 때 길고 활동적이며 활력 넘치는 삶을 나타낼 수 있습니다.`,} },
      { type: "paragraph", text: { en: `The 8th is also a Moksha house and often stimulates interest in personal transformation and spiritual growth.`, hi: `8वां मोक्ष भाव भी है और यह अक्सर व्यक्तिगत परिवर्तन और आध्यात्मिक विकास में रुचि को उत्तेजित करता है।`, ja: `8 番目はモクシャハウスでもあり、個人の変革と精神的な成長への関心を刺激することがよくあります。`, ko: `8하우스는 목샤(Moksha) 하우스이기도 하며 개인의 변화와 영적 성장에 대한 관심을 자극하는 경우가 많습니다.`,} },
      { type: "paragraph", text: { en: `According to some astrologers, it additionally governs chronic illnesses, long-term mental and physical conditions, and sexually transmitted diseases.`, hi: `कुछ ज्योतिषियों के अनुसार, यह पुरानी बीमारियों, दीर्घकालिक मानसिक और शारीरिक स्थितियों और यौन संचारित रोगों को भी नियंत्रित करता है।`, ja: `占星術師の中には、慢性疾患、長期にわたる精神的および身体的状態、性感染症も司るという人もいます。`, ko: `일부 점성가에 따르면 만성 질환, 장기적인 정신적, 육체적 상태, 성병을 추가로 관리합니다.`,} },
      { type: "paragraph", text: { en: `The 8th generally weakens planets occupying it (although exceptions exist), along with the houses ruled by those planets.`, hi: `8वां आम तौर पर उस पर स्थित ग्रहों को कमजोर करता है (हालांकि अपवाद मौजूद हैं), साथ ही उन ग्रहों द्वारा शासित घरों को भी कमजोर करता है।`, ja: `8番目は一般に、それを占める惑星（例外はありますが）と、それらの惑星が支配するハウスを弱体化させます。`, ko: `8하우스는 일반적으로 이를 점유하는 행성(예외가 존재하지만)과 해당 행성이 지배하는 하우스를 약화시킵니다.`,} },
      { type: "paragraph", text: { en: `House Classification: Dusthana / Moksha (Negative / Liberation)`, hi: `घर का वर्गीकरण: दुस्थान / मोक्ष (नकारात्मक / मुक्ति)`, ja: `ハウス分類: ダスターナ / モクシャ (ネガティブ / 解放)`, ko: `하우스 분류: Dusthana / Moksha(부정적 / 해방)`,} },
      { type: "paragraph", text: { en: `House Indicator: Saturn`, hi: `गृह सूचक: शनि`, ja: `ハウスインジケーター: 土星`, ko: `하우스 표시기: 토성`,} },
      { type: "heading", level: 3, text: { en: `Ninth House – ‘House of Fortune’`, hi: `नौवां घर - 'भाग्य का घर'`, ja: `9番目の家 – 「運命の家」`, ko: `아홉 번째 집 - '행운의 집'`,} },
      { type: "heading", level: 3, text: { en: `House Indications:`, hi: `घर के संकेत:`, ja: `ハウスの表示:`, ko: `주택 표시:`,} },
      { type: "paragraph", text: { en: `• Luck, fortune, and prosperity`, hi: `• भाग्य, भाग्य और समृद्धि`, ja: `• 幸運、富、繁栄`, ko: `• 행운, 행운, 번영`,} },
      { type: "paragraph", text: { en: `• Religion, faith, worship, spiritual teachers, law, and higher knowledge`, hi: `• धर्म, आस्था, पूजा, आध्यात्मिक शिक्षक, कानून और उच्च ज्ञान`, ja: `• 宗教、信仰、崇拝、精神的な教師、法律、および高度な知識`, ko: `• 종교, 신앙, 예배, 영적 교사, 법률 및 고등 지식`,} },
      { type: "paragraph", text: { en: `• Certain aspects of the relationship with one's father`, hi: `• किसी के पिता के साथ रिश्ते के कुछ पहलू`, ja: `• 父親との関係の特定の側面`, ko: `• 아버지와의 관계의 특정 측면`,} },
      { type: "paragraph", text: { en: `• Pilgrimages and long-distance travel`, hi: `• तीर्थयात्राएँ और लंबी दूरी की यात्राएँ`, ja: `• 巡礼と長距離旅行`, ko: `• 순례 및 장거리 여행`,} },
      { type: "paragraph", text: { en: `The 9th house is of equal importance to the 1st house.`, hi: `9वां घर पहले घर के समान महत्व रखता है।`, ja: `9ハウスは1ハウスと同じくらい重要です。`, ko: `9하우스는 1하우스와 마찬가지로 중요합니다.`,} },
      { type: "paragraph", text: { en: `It primarily signifies luck, fortune, and blessings in life.`, hi: `यह मुख्य रूप से जीवन में भाग्य, सौभाग्य और आशीर्वाद का प्रतीक है।`, ja: `それは主に人生における幸運、幸運、祝福を意味します。`, ko: `주로 행운, 행운, 인생의 축복을 의미합니다.`,} },
      { type: "paragraph", text: { en: `The 9th is generally regarded as the most auspicious house in the horoscope. Planets placed here tend to perform exceptionally well, and the ruler of the 9th carries a highly positive energy wherever it is located.`, hi: `कुंडली में नौवें भाव को आम तौर पर सबसे शुभ भाव माना जाता है। यहां स्थित ग्रह असाधारण रूप से अच्छा प्रदर्शन करते हैं, और नौवें भाव का शासक जहां भी स्थित होता है, वहां अत्यधिक सकारात्मक ऊर्जा होती है।`, ja: `9 室は一般に星占いで最も縁起の良い家とみなされています。ここに配置された惑星は非常に優れたパフォーマンスを発揮する傾向があり、9 番目の支配者はどこに配置されても非常にポジティブなエネルギーを運びます。`, ko: `9하우스는 일반적으로 별자리에서 가장 상서로운 하우스로 간주됩니다. 여기에 위치한 행성은 예외적으로 잘 수행되는 경향이 있으며, 9하우스의 룰러는 그것이 어디에 있든 매우 긍정적인 에너지를 전달합니다.`,} },
      { type: "paragraph", text: { en: `Some astrologers associate past-life credit more strongly with the 9th house than with the 5th.`, hi: `कुछ ज्योतिषी पिछले जीवन के श्रेय को 5वें घर की तुलना में 9वें घर से अधिक मजबूती से जोड़ते हैं।`, ja: `占星術師の中には、過去世の功績を、5 室よりも 9 室と強く結び付ける人もいます。`, ko: `일부 점성가들은 전생 신용을 5하우스보다 9하우스와 더 강하게 연관시킵니다.`,} },
      { type: "paragraph", text: { en: `A strong 9th house can bestow tremendous good fortune and a sense of divine grace.`, hi: `एक मजबूत नौवां घर जबरदस्त सौभाग्य और दैवीय कृपा की भावना प्रदान कर सकता है।`, ja: `強い9ハウスは、途方もない幸運と神の恵みの感覚を与えることができます。`, ko: `강한 9하우스는 엄청난 행운과 신성한 은총을 선사할 수 있습니다.`,} },
      { type: "paragraph", text: { en: `A person's relationship with their spiritual teacher is seen through the 9th house. Traditionally in India, the father often fulfilled this role during childhood before a spiritual guru was encountered later in life. Consequently, some aspects of the father-child relationship are also examined through the 9th house.`, hi: `नौवें भाव से व्यक्ति का अपने आध्यात्मिक गुरु के साथ संबंध देखा जाता है। परंपरागत रूप से भारत में, पिता अक्सर बचपन के दौरान इस भूमिका को निभाते थे, इससे पहले कि जीवन में बाद में किसी आध्यात्मिक गुरु का सामना होता। परिणामस्वरूप, पिता-संतान संबंध के कुछ पहलुओं की जांच भी नवम भाव से की जाती है।`, ja: `精神的な教師との関係は、9 ハウスを通して見られます。インドでは伝統的に、父親が幼少期にこの役割を果たし、その後、霊的な指導者に出会うことがよくありました。したがって、父と子の関係のいくつかの側面も、9 ハウスを通じて検査されます。`, ko: `사람과 영적 스승과의 관계는 9하우스를 통해 볼 수 있습니다. 전통적으로 인도에서는 나중에 영적 스승을 만나기 전인 어린 시절에 아버지가 이 역할을 수행하는 경우가 많았습니다. 따라서 9하우스를 통해 부자관계의 일부 측면도 검토된다.`,} },
      { type: "paragraph", text: { en: `House Classification: Trikona / Dharma (Trinal / Action)`, hi: `घर का वर्गीकरण: त्रिकोण / धर्म (त्रिनल / क्रिया)`, ja: `ハウス分類: トリコナ / ダルマ (トリナル / アクション)`, ko: `하우스 분류: Trikona / Dharma(Trinal / Action)`,} },
      { type: "paragraph", text: { en: `House Indicator: Jupiter`, hi: `गृह सूचक: बृहस्पति`, ja: `ハウスインジケーター: 木星`, ko: `하우스 표시기: 목성`,} },
      { type: "heading", level: 3, text: { en: `Tenth House – ‘House of Status and Power’`, hi: `दसवां घर - 'स्थिति और शक्ति का घर'`, ja: `第10ハウス – 「地位と権力のハウス」`, ko: `열 번째 집 - '지위와 권력의 집'`,} },
      { type: "heading", level: 3, text: { en: `House Indications:`, hi: `घर के संकेत:`, ja: `ハウスの表示:`, ko: `주택 표시:`,} },
      { type: "paragraph", text: { en: `• Career, status, and reputation`, hi: `• कैरियर, स्थिति और प्रतिष्ठा`, ja: `• キャリア、地位、評判`, ko: `• 경력, 지위, 평판`,} },
      { type: "paragraph", text: { en: `• Fame and professional achievement`, hi: `• प्रसिद्धि और व्यावसायिक उपलब्धि`, ja: `• 名声と職業上の業績`, ko: `• 명성과 직업적 성취`,} },
      { type: "paragraph", text: { en: `• Authority figures, government officials, and institutions`, hi: `• प्राधिकरण के आंकड़े, सरकारी अधिकारी और संस्थान`, ja: `• 権威者、政府関係者、および機関`, ko: `• 당국 인사, 정부 관료 및 기관`,} },
      { type: "paragraph", text: { en: `• The status, authority, and influence of the father`, hi: `• पिता की स्थिति, अधिकार और प्रभाव`, ja: `• 父親の地位、権威、影響力`, ko: `• 아버지의 지위, 권위, 영향력`,} },
      { type: "paragraph", text: { en: `The 10th house indicates the degree of success, recognition, and professional standing we may achieve in our chosen career.`, hi: `दसवां घर हमारे द्वारा चुने गए करियर में सफलता, मान्यता और पेशेवर स्थिति की डिग्री को दर्शाता है।`, ja: `10ハウスは、私たちが選択したキャリアで達成できる成功、評価、専門的地位の程度を示します。`, ko: `10하우스는 우리가 선택한 직업에서 달성할 수 있는 성공, 인정, 직업적 지위의 정도를 나타냅니다.`,} },
      { type: "paragraph", text: { en: `It is an Upachaya or growing house, where malefic planets can perform well, provided they are not debilitated or adversely affected.`, hi: `यह एक उपचय या बढ़ता घर है, जहां अशुभ ग्रह अच्छा प्रदर्शन कर सकते हैं, बशर्ते वे कमजोर या प्रतिकूल प्रभाव में न हों।`, ja: `それはウパチャヤまたは成長ハウスであり、弱体化または悪影響を受けない限り、凶星がうまく機能できる場所です。`, ko: `이는 우파차야(Upachaya) 또는 성장하는 집으로, 흉성 행성이 쇠약해지거나 부정적인 영향을 받지 않는 한 잘 수행될 수 있습니다.`,} },
      { type: "paragraph", text: { en: `Many important factors relating to a person's father are also assessed from the 10th house.`, hi: `दसवें भाव से व्यक्ति के पिता से संबंधित कई महत्वपूर्ण कारकों का भी आकलन किया जाता है।`, ja: `人の父親に関する多くの重要な要素も、10 ハウスから評価されます。`, ko: `사람의 아버지와 관련된 많은 중요한 요소도 10하우스에서 평가됩니다.`,} },
      { type: "paragraph", text: { en: `House Classification: Kendra / Upachaya / Artha (Angular / Growing / Wealth)`, hi: `मकान का वर्गीकरण: केंद्र / उपचय / अर्थ (कोणीय / वृद्धि / धन)`, ja: `ハウス分類: ケンドラ / ウパチャヤ / アーサ (角張った / 成長 / 富)`, ko: `주택 분류: Kendra / Upachaya / Artha(각도 / 성장 / 부)`,} },
      { type: "paragraph", text: { en: `House Indicator: Mercury`, hi: `गृह सूचक: बुध`, ja: `ハウスインジケーター: 水星`, ko: `하우스 표시기: 수성`,} },
      { type: "heading", level: 3, text: { en: `Eleventh House – ‘House of Gains, Profits and Desires’`, hi: `ग्यारहवाँ घर - 'लाभ, लाभ और इच्छाओं का घर'`, ja: `11番目の家 – 「利益、利益、欲望の家」`, ko: `열한 번째 하우스 - '이익, 이익, 욕망의 하우스'`,} },
      { type: "heading", level: 3, text: { en: `House Indications:`, hi: `घर के संकेत:`, ja: `ハウスの表示:`, ko: `주택 표시:`,} },
      { type: "paragraph", text: { en: `• Gains, profits, and income`, hi: `• लाभ, मुनाफ़ा और आय`, ja: `• 利益、利益、収入`, ko: `• 이익, 이익 및 소득`,} },
      { type: "paragraph", text: { en: `• Desires, wishes, ambitions, and opportunities`, hi: `• इच्छाएँ, कामनाएँ, महत्त्वाकांक्षाएँ और अवसर`, ja: `• 願望、希望、野心、機会`, ko: `• 욕망, 소원, 야망 및 기회`,} },
      { type: "paragraph", text: { en: `The 11th house differs from the 2nd in that it governs gains and profits obtained by any means. Therefore, even if the 2nd house is weak, substantial income may still be generated, although this does not necessarily result in accumulated wealth.`, hi: `11वां घर दूसरे से अलग है क्योंकि यह किसी भी माध्यम से प्राप्त लाभ और मुनाफ़े को नियंत्रित करता है। इसलिए, भले ही दूसरा घर कमजोर हो, फिर भी पर्याप्त आय उत्पन्न हो सकती है, हालांकि जरूरी नहीं कि इसका परिणाम संचित धन हो।`, ja: `11ハウスは、何らかの手段で得た利得や利益を司るという点で2ハウスとは異なります。したがって、2ハウスが弱くても、必ずしも富の蓄積につながるわけではありませんが、かなりの収入が得られる可能性があります。`, ko: `11하우스는 어떤 수단으로든 얻는 이득과 이익을 관장한다는 점에서 2하우스와 다릅니다. 따라서 2집이 약하더라도 반드시 부의 축적으로 이어지지는 않더라도 상당한 소득이 발생할 수 있습니다.`,} },
      { type: "paragraph", text: { en: `The 11th house governs the fulfilment of major desires and ambitions. A strong 11th brings opportunities that enable a person to realise their goals.`, hi: `11वां भाव प्रमुख इच्छाओं और महत्वाकांक्षाओं की पूर्ति को नियंत्रित करता है। एक मजबूत 11वां अवसर लाता है जो व्यक्ति को अपने लक्ष्यों को प्राप्त करने में सक्षम बनाता है।`, ja: `11室は主要な願望や野心の実現を支配します。強い11は、人が自分の目標を実現できる機会をもたらします。`, ko: `11하우스는 주요 욕망과 야망의 성취를 관장합니다. 강한 11번째는 개인이 자신의 목표를 실현할 수 있는 기회를 제공합니다.`,} },
      { type: "paragraph", text: { en: `Like other Upachaya houses, malefic planets can eventually produce favourable results here.`, hi: `अन्य उपचय घरों की तरह, यहां भी अशुभ ग्रह अंततः अनुकूल परिणाम दे सकते हैं।`, ja: `他のウパチャヤハウスと同様に、凶星はここでも最終的に好ましい結果を生み出す可能性があります。`, ko: `다른 우파차야 하우스와 마찬가지로 흉성 행성도 결국 여기에서 유리한 결과를 낳을 수 있습니다.`,} },
      { type: "paragraph", text: { en: `House Classification: Upachaya / Kama (Growing / Desire)`, hi: `गृह वर्गीकरण: उपचय/काम (बढ़ती/इच्छा)`, ja: `ハウス分類: ウパチャヤ / カーマ (成長 / 欲望)`, ko: `주택 분류: 우파차야/카마(성장/욕망)`,} },
      { type: "paragraph", text: { en: `House Indicator: Jupiter`, hi: `गृह सूचक: बृहस्पति`, ja: `ハウスインジケーター: 木星`, ko: `하우스 표시기: 목성`,} },
      { type: "heading", level: 3, text: { en: `Twelfth House – ‘House of Loss and Expenditure’`, hi: `बारहवां घर - 'हानि और व्यय का घर'`, ja: `12番目の家 – 「損失と支出の家」`, ko: `열두 번째 집 - '손실과 지출의 집'`,} },
      { type: "heading", level: 3, text: { en: `House Indications:`, hi: `घर के संकेत:`, ja: `ハウスの表示:`, ko: `주택 표시:`,} },
      { type: "paragraph", text: { en: `• Expenditure, financial loss, and waste`, hi: `• व्यय, वित्तीय हानि और बर्बादी`, ja: `• 支出、経済的損失、無駄`, ko: `• 지출, 금전적 손실, 낭비`,} },
      { type: "paragraph", text: { en: `• Misfortune`, hi: `• दुर्भाग्य`, ja: `• 不幸`, ko: `• 불행`,} },
      { type: "paragraph", text: { en: `• Salvation, liberation, and enlightenment`, hi: `• मुक्ति, मुक्ति और आत्मज्ञान`, ja: `• 救い、解放、啓発`, ko: `• 구원, 해방, 깨달음`,} },
      { type: "paragraph", text: { en: `• Journeys to distant lands`, hi: `• दूर देशों की यात्राएँ`, ja: `• 遠い国への旅`, ko: `• 먼 나라로의 여행`,} },
      { type: "paragraph", text: { en: `The 12th house governs all forms of loss and expenditure.`, hi: `12वां भाव सभी प्रकार के नुकसान और व्यय को नियंत्रित करता है।`, ja: `12室はあらゆる形態の損失と支出を管理します。`, ko: `12하우스는 모든 형태의 손실과 지출을 관장합니다.`,} },
      { type: "paragraph", text: { en: `A strong 12th house helps preserve and protect accumulated wealth.`, hi: `एक मजबूत 12वां घर संचित धन को सुरक्षित रखने में मदद करता है।`, ja: `強い12ハウスは、蓄積された富を維持し、保護するのに役立ちます。`, ko: `강력한 12하우스는 축적된 부를 보존하고 보호하는 데 도움이 됩니다.`,} },
      { type: "paragraph", text: { en: `It also indicates progress toward higher states of consciousness, spiritual development, and eventual enlightenment.`, hi: `यह चेतना की उच्च अवस्थाओं, आध्यात्मिक विकास और अंततः ज्ञानोदय की दिशा में प्रगति का भी संकेत देता है।`, ja: `また、より高い意識状態、精神的な発達、そして最終的な悟りに向けた進歩も示しています。`, ko: `이는 또한 더 높은 의식 상태, 영적 발전, 궁극적인 깨달음을 향한 진전을 나타냅니다.`,} },
      { type: "paragraph", text: { en: `Planets placed here are generally weakened (although there are exceptions), and the houses they rule may also be adversely affected.`, hi: `यहां स्थित ग्रह आम तौर पर कमजोर होते हैं (हालांकि कुछ अपवाद भी हैं), और जिन घरों पर उनका शासन होता है उन पर भी प्रतिकूल प्रभाव पड़ सकता है।`, ja: `ここに配置された惑星は（例外もありますが）一般に弱体化し、支配するハウスにも悪影響が及ぶ可能性があります。`, ko: `여기에 배치된 행성은 일반적으로 약해지며(예외도 있지만) 그들이 지배하는 하우스도 부정적인 영향을 받을 수 있습니다.`,} },
      { type: "paragraph", text: { en: `House Classification: Dusthana / Moksha (Negative / Liberation)`, hi: `घर का वर्गीकरण: दुस्थान / मोक्ष (नकारात्मक / मुक्ति)`, ja: `ハウス分類: ダスターナ / モクシャ (ネガティブ / 解放)`, ko: `하우스 분류: Dusthana / Moksha(부정적 / 해방)`,} },
      { type: "paragraph", text: { en: `House Indicator: Saturn`, hi: `गृह सूचक: शनि`, ja: `ハウスインジケーター: 土星`, ko: `하우스 표시기: 토성`,} },
      { type: "heading", level: 3, text: { en: `Parts of the Body Associated with Each House`, hi: `प्रत्येक घर से जुड़े शरीर के अंग`, ja: `各家に関係する体の部位`, ko: `각 집과 관련된 신체 부위`,} },
      { type: "paragraph", text: { en: `Each house corresponds to a particular part of the body. When a house is significantly weakened, it may indicate potential health issues affecting the related area of the physiology.`, hi: `प्रत्येक भाव शरीर के एक विशेष अंग से मेल खाता है। जब कोई घर काफी कमजोर हो जाता है, तो यह शरीर विज्ञान के संबंधित क्षेत्र को प्रभावित करने वाले संभावित स्वास्थ्य मुद्दों का संकेत दे सकता है।`, ja: `各ハウスは体の特定の部分に対応します。家が著しく弱っている場合、生理機能の関連領域に影響を与える潜在的な健康上の問題を示している可能性があります。`, ko: `각 집은 신체의 특정 부분에 해당합니다. 집이 크게 약해지면 생리학 관련 영역에 영향을 미치는 잠재적인 건강 문제를 나타낼 수 있습니다.`,} },
      { type: "table", headers: [{ en: `House`, hi: `घर`, ja: `ハウス`, ko: `집`,}, { en: `Part of Body`, hi: `शरीर का अंग`, ja: `身体部位`, ko: `신체의 일부`,}], rows: [
        [{ en: `1`, hi: `1`, ja: `1`, ko: `1`,}, { en: `Head`, hi: `सिर`, ja: `頭`, ko: `머리`,}],
        [{ en: `2`, hi: `2`, ja: `2`, ko: `2`,}, { en: `Eyes, face, mouth, upper throat`, hi: `आंखें, चेहरा, मुंह, ऊपरी गला`, ja: `目、顔、口、喉上部`, ko: `눈, 얼굴, 입, 목 윗부분`,}],
        [{ en: `3`, hi: `3`, ja: `3`, ko: `3`,}, { en: `Arms, shoulders, lower throat`, hi: `भुजाएँ, कंधे, निचला गला`, ja: `腕、肩、喉下部`, ko: `팔, 어깨, 목 아래`,}],
        [{ en: `4`, hi: `4`, ja: `4`, ko: `4`,}, { en: `Chest, heart`, hi: `छाती, हृदय`, ja: `胸、心臓`, ko: `가슴, 심장`,}],
        [{ en: `5`, hi: `5`, ja: `5`, ko: `5`,}, { en: `Stomach`, hi: `पेट`, ja: `胃`, ko: `위`,}],
        [{ en: `6`, hi: `6`, ja: `6`, ko: `6`,}, { en: `Region of the navel`, hi: `नाभि का क्षेत्र`, ja: `へそ周辺`, ko: `배꼽 부위`,}],
        [{ en: `7`, hi: `7`, ja: `7`, ko: `7`,}, { en: `Body below the waist`, hi: `कमर के नीचे का शरीर`, ja: `腰から下の体`, ko: `허리 아래의 신체`,}],
        [{ en: `8`, hi: `8`, ja: `8`, ko: `8`,}, { en: `Reproductive organs, anus`, hi: `प्रजनन अंग, गुदा`, ja: `生殖器、肛門`, ko: `생식기관, 항문`,}],
        [{ en: `9`, hi: `9`, ja: `9`, ko: `9`,}, { en: `Hips, thighs`, hi: `कूल्हे, जांघें`, ja: `腰、太もも`, ko: `엉덩이, 허벅지`,}],
        [{ en: `10`, hi: `10`, ja: `10`, ko: `10`,}, { en: `Knees`, hi: `घुटनों`, ja: `膝`, ko: `무릎`,}],
        [{ en: `11`, hi: `11`, ja: `11`, ko: `11`,}, { en: `Calves`, hi: `बछड़ों`, ja: `ふくらはぎ`, ko: `송아지`,}],
        [{ en: `12`, hi: `12`, ja: `12`, ko: `12`,}, { en: `Feet`, hi: `पैर`, ja: `足`, ko: `피트`,}],
      ] },
      { type: "heading", level: 3, text: { en: `House Classification`, hi: `मकान का वर्गीकरण`, ja: `住宅の分類`, ko: `주택 분류`,} },
      { type: "paragraph", text: { en: `Houses 5 and 9 (Trikona) are regarded as exceptionally auspicious. Planets placed in these houses become strengthened, and the houses they rule also benefit from their placement in the 5th or 9th.`, hi: `भाव 5 और 9 (त्रिकोण) अत्यंत शुभ माने जाते हैं। इन घरों में स्थित ग्रह मजबूत हो जाते हैं, और जिन घरों पर वे शासन करते हैं उन्हें भी 5वें या 9वें में उनके स्थान से लाभ होता है।`, ja: `ハウス 5 ​​と 9 (トリコナ) は、非常に縁起が良いと考えられています。これらのハウスに配置された惑星は強化され、それらが支配するハウスも5室または9室に配置されることで恩恵を受けます。`, ko: `하우스 5와 9(Trikona)는 매우 상서로운 것으로 간주됩니다. 이 하우스에 배치된 행성은 강화되고, 그들이 지배하는 하우스도 5하우스나 9하우스에 배치하면 이익을 얻습니다.`,} },
      { type: "paragraph", text: { en: `In addition, the rulers of the 5th and 9th houses—even if naturally malefic planets such as Saturn—become functional benefics and carry a positive influence wherever they are placed.`, hi: `इसके अलावा, 5वें और 9वें घरों के शासक - भले ही शनि जैसे स्वाभाविक रूप से हानिकारक ग्रह हों - कार्यात्मक लाभकारी बन जाते हैं और जहां भी वे स्थित होते हैं, सकारात्मक प्रभाव डालते हैं।`, ja: `さらに、5 室と 9 室の支配星は、たとえ土星のような本来的に凶星であっても、機能的な恩恵をもたらし、どこに配置されてもポジティブな影響を及ぼします。`, ko: `게다가, 5하우스와 9하우스의 룰러들은 비록 토성과 같은 본래 흉한 행성이라 할지라도 기능적 혜택이 되어 어디에 위치하든 긍정적인 영향을 미칩니다.`,} },
      { type: "paragraph", text: { en: `Houses 6, 8, and 12 (Dusthana) are considered challenging houses. Planets occupying them tend to become weakened, and the houses ruled by those planets may also suffer.`, hi: `मकान 6, 8, और 12 (दुस्थान) चुनौतीपूर्ण मकान माने जाते हैं। उन पर स्थित ग्रह कमजोर हो जाते हैं, और उन ग्रहों द्वारा शासित घरों को भी नुकसान हो सकता है।`, ja: `ハウス 6、8、12 (ダスターナ) は、難しいハウスとみなされます。それらを占める惑星は弱くなる傾向があり、それらの惑星によって支配される家も苦しむ可能性があります。`, ko: `하우스 6, 8, 12(Dusthana)는 도전적인 하우스로 간주됩니다. 이를 점유하는 행성은 약화되는 경향이 있으며, 해당 행성이 지배하는 하우스도 어려움을 겪을 수 있습니다.`,} },
      { type: "paragraph", text: { en: `The rulers of the 6th, 8th, and 12th houses often create difficulties somewhere in the chart, even if they are naturally benefic planets such as Jupiter. This generally applies unless the planet also rules one of the auspicious houses, namely the 5th or 9th.`, hi: `6ठे, 8वें और 12वें भाव के शासक अक्सर चार्ट में कहीं न कहीं कठिनाइयाँ पैदा करते हैं, भले ही वे बृहस्पति जैसे स्वाभाविक रूप से लाभकारी ग्रह हों। यह आम तौर पर तब तक लागू होता है जब तक कि ग्रह शुभ घरों में से किसी एक, अर्थात् 5वें या 9वें पर भी शासन न करता हो।`, ja: `6、8、12 ハウスの支配星は、たとえ木星のような本来的に有益な惑星であっても、チャートのどこかに困難を引き起こすことがよくあります。これは、惑星が縁起の良いハウス、つまり 5 室または 9 室のいずれかを支配している場合を除いて、一般的に当てはまります。`, ko: `6하우스, 8하우스, 12하우스의 룰러들은 목성과 같이 선천적으로 유익한 행성이라 할지라도 차트 어딘가에서 종종 어려움을 겪습니다. 이는 행성이 상서로운 하우스 중 하나, 즉 5하우스 또는 9하우스를 지배하지 않는 한 일반적으로 적용됩니다.`,} },
      { type: "paragraph", text: { en: `Houses 3, 6, 10, and 11 form the special category known as Upachaya or "growing" houses. Malefic planets tend to perform well in these houses and eventually produce beneficial results. Difficulties indicated by these houses often diminish with time.`, hi: `मकान 3, 6, 10, और 11 विशेष श्रेणी बनाते हैं जिन्हें उपचय या "बढ़ते" मकानों के रूप में जाना जाता है। इन घरों में अशुभ ग्रह अच्छा प्रदर्शन करते हैं और अंततः लाभकारी परिणाम देते हैं। इन भावों द्वारा बताई गई कठिनाइयाँ समय के साथ अक्सर कम हो जाती हैं।`, ja: `ハウス 3、6、10、および 11 は、ウパチャヤまたは「成長する」ハウスとして知られる特別なカテゴリーを形成します。凶星はこれらのハウスでうまく機能し、最終的には有益な結果を生み出す傾向があります。これらのハウスが示す困難は、時間の経過とともに軽減されることがよくあります。`, ko: `주택 3, 6, 10, 11은 Upachaya 또는 "성장하는" 주택으로 알려진 특별한 범주를 형성합니다. 흉성 행성은 이러한 하우스에서 잘 수행되는 경향이 있으며 결국 유익한 결과를 낳습니다. 이러한 주택에서 나타나는 어려움은 시간이 지나면서 사라지는 경우가 많습니다.`,} },
      { type: "paragraph", text: { en: `Houses 1, 4, 7, and 10 are known as Kendras or angular houses. Planets placed within them are strengthened.`, hi: `मकान 1, 4, 7, और 10 को केंद्र या कोणीय मकान के रूप में जाना जाता है। इनके अंदर स्थित ग्रह मजबूत होते हैं।`, ja: `ハウス 1、4、7、および 10 は、ケンドラまたは角のあるハウスとして知られています。その中に配置された惑星は強化されます。`, ko: `하우스 1, 4, 7, 10은 Kendras 또는 앵귤러 하우스로 알려져 있습니다. 그 안에 배치된 행성은 강화됩니다.`,} },
      { type: "paragraph", text: { en: `The houses are also grouped into repeating cycles of four:`, hi: `घरों को भी चार के दोहराव वाले चक्रों में बांटा गया है:`, ja: `ハウスは、次の 4 つの繰り返しサイクルにもグループ化されます。`, ko: `주택은 또한 4개의 반복 주기로 그룹화됩니다.`,} },
      { type: "paragraph", text: { en: `• Dharma (Duty and evolutionary action)`, hi: `• धर्म (कर्तव्य और विकासवादी कार्रवाई)`, ja: `• ダルマ（義務と進化的行動）`, ko: `• 달마(의무와 진화작용)`,} },
      { type: "paragraph", text: { en: `• Artha (Wealth)`, hi: `• अर्थ (धन)`, ja: `• アーサ（富）`, ko: `• 아르타(부)`,} },
      { type: "paragraph", text: { en: `• Kama (Desire)`, hi: `• काम (इच्छा)`, ja: `• カーマ (欲望)`, ko: `• 카마(욕망)`,} },
      { type: "paragraph", text: { en: `• Moksha (Liberation)`, hi: `• मोक्ष (मुक्ति)`, ja: `• モクシャ (解放)`, ko: `• 목샤(해방)`,} },
      { type: "paragraph", text: { en: `This pattern begins with the 1st house and repeats throughout the horoscope. Thus, the 5th house is Dharma, the 6th Artha, the 7th Kama, the 8th Moksha, and the cycle repeats again through the 9th to the 12th houses.`, hi: `यह पैटर्न पहले घर से शुरू होता है और संपूर्ण कुंडली में दोहराया जाता है। इस प्रकार, 5वां घर धर्म है, 6वां अर्थ है, 7वां काम है, 8वां मोक्ष है, और चक्र 9वें से 12वें घर तक फिर से दोहराया जाता है।`, ja: `このパターンは第 1 ハウスから始まり、ホロスコープ全体で繰り返されます。したがって、５室はダルマ、６室はアルタ、７室はカーマ、８室はモクシャであり、このサイクルは９室から１２室まで再び繰り返される。`, ko: `이 패턴은 1하우스에서 시작하여 별자리 전체에서 반복됩니다. 따라서 5하우스는 달마(Dharma), 6하우스 아르타(Artha), 7하우스 카마(Kama), 8하우스 목샤(Moksha)이며, 이 순환은 9하우스에서 12하우스까지 다시 반복됩니다.`,} },
      { type: "heading", level: 3, text: { en: `Footnotes`, hi: `फुटनोट`, ja: `脚注`, ko: `각주`,} },
      { type: "paragraph", text: { en: `[1] When we describe a house as "strong," we are considering factors such as the strength and status of the ruling planet (for example, Exalted or Own Sign status), the house occupied by the ruler (for example, placement in the auspicious 9th house), benefic planets occupying the house, and positive aspects from natural benefics such as Jupiter.`, hi: `[1] जब हम किसी घर को "मजबूत" बताते हैं, तो हम शासक ग्रह की ताकत और स्थिति (उदाहरण के लिए, उच्च या स्वयं की राशि की स्थिति), शासक द्वारा कब्जा किया गया घर (उदाहरण के लिए, शुभ 9वें घर में स्थिति), घर में रहने वाले लाभकारी ग्रह, और बृहस्पति जैसे प्राकृतिक लाभ से सकारात्मक पहलू जैसे कारकों पर विचार कर रहे हैं।`, ja: `[1] 私たちがハウスを「強い」と表現するとき、支配星の強さとステータス (例えば、高揚または自身のサインのステータス)、支配星が占有するハウス (例えば、縁起の良い 9 ハウスへの配置)、ハウスを占有する恩恵を受ける惑星、および木星などの自然の恩恵をもたらすポジティブな側面などの要素を考慮します。`, ko: `[1] 하우스를 "강하다"고 설명할 때, 우리는 지배 행성의 힘과 상태(예: 엑절티드 또는 고유 별자리 상태), 룰러가 차지하는 하우스(예: 상서로운 9번째 하우스에 배치), 하우스를 차지하는 유익한 행성, 목성과 같은 자연적 혜택의 긍정적인 측면과 같은 요소를 고려합니다.`,} },
      { type: "paragraph", text: { en: `[2] We can further evaluate a house by examining the condition and well-being of its indicator planet. While this is generally less important than factors such as the house ruler, occupying planets, and aspects, it can still modify our interpretation. The natural significations of the indicator planet often correspond closely with the affairs of the house. For example, Venus naturally signifies love, affection, and passion, which aligns well with the 7th house and its association with marriage and partnerships.`, hi: `[2] हम किसी भाव का मूल्यांकन उसके सूचक ग्रह की स्थिति और भलाई की जांच करके कर सकते हैं। हालांकि यह आम तौर पर घर के शासक, कब्जे वाले ग्रहों और पहलुओं जैसे कारकों से कम महत्वपूर्ण है, फिर भी यह हमारी व्याख्या को संशोधित कर सकता है। सूचक ग्रह का प्राकृतिक महत्व अक्सर घर के मामलों से निकटता से मेल खाता है। उदाहरण के लिए, शुक्र स्वाभाविक रूप से प्यार, स्नेह और जुनून का प्रतीक है, जो 7वें घर और विवाह और साझेदारी के साथ इसके संबंध के साथ अच्छी तरह से मेल खाता है।`, ja: `[2] 指標となる惑星の状態と幸福度を調べることで、住宅をさらに評価することができます。これは一般に、ハウスルーラー、占有惑星、アスペクトなどの要素ほど重要ではありませんが、それでも解釈を変更する可能性があります。指標惑星の自然な意味は、家の事柄と密接に対応していることがよくあります。たとえば、金星は本来、愛、愛情、情熱を表し、7 ハウスと結婚やパートナーシップとの関連性とよく一致します。`, ko: `[2] 우리는 지표 행성의 상태와 안녕을 조사함으로써 집을 더 평가할 수 있습니다. 이것은 일반적으로 하우스 룰러, 점유 행성 및 측면과 같은 요소보다 덜 중요하지만 여전히 우리의 해석을 수정할 수 있습니다. 지표 행성의 자연적 의미는 종종 하우스의 일과 밀접하게 일치합니다. 예를 들어, 금성은 자연스럽게 사랑, 애정, 열정을 의미하며, 이는 7하우스와 결혼 및 파트너십과의 연관성과 잘 어울립니다.`,} },
    ],
  }
];
